(508, 'customize_stashed_theme_mods', 'a:1:{s:9:\"petstudio\";a:11:{s:28:\"pawfect_contact_faq_repeater\";a:4:{s:5:\"value\";s:1253:\"[{\"text\":\"We offer a 30-day return policy on all unused items in their original packaging. Please visit our returns page for more details on how to initiate a return.\",\"title\":\"What is your return policy?\",\"subtitle\":\"undefined\",\"social_repeater\":\"undefined\",\"id\":\"customizer_repeater_faq_001\",\"shortcode\":\"undefined\",\"text_two\":\"undefined\",\"text_three\":\"undefined\",\"position_preset\":\"undefined\",\"product_select\":\"undefined\"},{\"text\":\"All of our bed covers are removable and machine-washable. We recommend washing on a gentle cycle with cold water and air drying to maintain its shape and softness.\",\"title\":\"How do I care for my plush bed?\",\"subtitle\":\"undefined\",\"social_repeater\":\"undefined\",\"id\":\"customizer_repeater_faq_002\",\"shortcode\":\"undefined\",\"text_two\":\"undefined\",\"text_three\":\"undefined\",\"position_preset\":\"undefined\",\"product_select\":\"undefined\"},{\"text\":\"Yes, we ship to most countries worldwide. Shipping costs and times will be calculated at checkout based on your location.\",\"title\":\"Do you ship internationally?\",\"subtitle\":\"undefined\",\"social_repeater\":\"undefined\",\"id\":\"customizer_repeater_faq_003\",\"shortcode\":\"undefined\",\"text_two\":\"undefined\",\"text_three\":\"undefined\",\"position_preset\":\"undefined\",\"product_select\":\"undefined\"}]\";s:4:\"type\";s:9:\"theme_mod\";s:7:\"user_id\";i:1;s:17:\"date_modified_gmt\";s:19:\"2026-11-11 07:03:22\";}s:27:\"pawfect_main_slider_content\";a:4:{s:5:\"value\";s:336:\"[{\"text\":\"\",\"link\":\"\",\"page\":\"\",\"image_url\":\"\",\"title\":\"\",\"subtitle\":\"\",\"social_repeater\":\"undefined\",\"id\":\"customizer-repeater-6af4130b4791e\",\"shortcode\":\"undefined\",\"text_two\":\"undefined\",\"text_three\":\"undefined\",\"position_preset\":\"undefined\",\"product_select\":\"unde