adding\":{\"unit\":\"px\",\"top\":\"0\",\"right\":\"0\",\"bottom\":\"0\",\"left\":\"0\",\"isLinked\":true},\"width_tablet\":{\"size\":100,\"unit\":\"%\"},\"content_width\":\"full\",\"flex_gap\":{\"column\":\"50\",\"row\":\"50\",\"isLinked\":true,\"unit\":\"px\",\"size\":50},\"flex_gap_tablet\":{\"column\":\"40\",\"row\":\"40\",\"isLinked\":true,\"unit\":\"px\",\"size\":40}},\"elements\":[{\"id\":\"c8c834f\",\"elType\":\"widget\",\"settings\":{\"title\":\"HSB-VNU\",\"__globals__\":{\"title_color\":\"globals\\/colors?id=blocksy_palette_8\"},\"typography_typography\":\"custom\",\"typography_font_size_tablet\":{\"unit\":\"px\",\"size\":30,\"sizes\":[]}},\"elements\":[],\"widgetType\":\"heading\"},{\"id\":\"c7e9dde\",\"elType\":\"container\",\"settings\":{\"flex_gap\":{\"size\":20,\"column\":\"20\",\"row\":\"20\",\"unit\":\"px\",\"isLinked\":true},\"structure\":\"20\",\"flex_direction\":\"row\",\"flex_align_items\":\"stretch\",\"content_width\":\"full\",\"padding\":{\"unit\":\"px\",\"top\":\"0\",\"right\":\"0\",\"bottom\":\"0\",\"left\":\"0\",\"isLinked\":true}},\"elements\":[{\"id\":\"962b41a\",\"elType\":\"widget\",\"settings\":{\"editor\":\"<p>Since its establishment in 1995 under Vietnam National University, Hanoi, Hanoi School of Business and Management (HSB) has consistently pursued the vision of becoming a pioneering institution in internationally accredited business and management education and research, while contributing to the sustainable development of Vietnam. Through an interdisciplinary approach integrating three academic pillars \\u2014 Management, Security, and Technology \\u2014 HSB offers a distinctive model of education and research aimed at addressing practical challenges in an increasingly dynamic global context, shaping up future leaders in both public and private sectors<\\/p>\",\"__globals__\":{\"text_color\":\"globals\\/colors?id=blocksy_palette_8\"}},\"elements\":[],\"widgetType\":\"text-editor\"},{\"id\":\"c444ab9\",\"elType\":\"widget\",\"set