opdown g\\u1ee3i \\u00fd \\u0111\\u1ecba \\u0111i\\u1ec3m *\\/\\r\\n  #wpCarRentalPC .crpc-loc-dropdown {\\r\\n    display: none;\\r\\n    position: absolute;\\r\\n    top: calc(100% + 14px);\\r\\n    left: -12px;\\r\\n    width: 360px;\\r\\n    max-width: 90vw;\\r\\n    background-color: #161a23;\\r\\n    border: 1px solid #2d3444;\\r\\n    border-radius: 12px;\\r\\n    padding: 8px;\\r\\n    box-shadow: 0 16px 32px rgba(0, 0, 0, 0.65);\\r\\n    z-index: 50;\\r\\n    animation: crpcFadeDown 0.18s ease-out;\\r\\n  }\\r\\n\\r\\n  #wpCarRentalPC .crpc-loc-dropdown.open {\\r\\n    display: block;\\r\\n  }\\r\\n\\r\\n  #wpCarRentalPC .crpc-loc-header {\\r\\n    font-size: 11px;\\r\\n    font-weight: 700;\\r\\n    text-transform: uppercase;\\r\\n    color: #6b7280;\\r\\n    padding: 6px 10px;\\r\\n    letter-spacing: 0.5px;\\r\\n  }\\r\\n\\r\\n  #wpCarRentalPC .crpc-loc-item {\\r\\n    display: flex;\\r\\n    align-items: center;\\r\\n    gap: 10px;\\r\\n    padding: 10px;\\r\\n    border-radius: 8px;\\r\\n    cursor: pointer;\\r\\n    transition: background-color 0.15s ease;\\r\\n  }\\r\\n\\r\\n  #wpCarRentalPC .crpc-loc-item:hover {\\r\\n    background-color: #212734;\\r\\n  }\\r\\n\\r\\n  #wpCarRentalPC .crpc-loc-item-title {\\r\\n    font-size: 13px;\\r\\n    font-weight: 600;\\r\\n    color: #f3f4f6;\\r\\n  }\\r\\n\\r\\n  #wpCarRentalPC .crpc-loc-item-sub {\\r\\n    font-size: 11px;\\r\\n    color: #9ca3af;\\r\\n  }\\r\\n\\r\\n  #wpCarRentalPC .crpc-time-display {\\r\\n    font-size: 15px;\\r\\n    font-weight: 700;\\r\\n    color: #ffffff;\\r\\n    cursor: pointer;\\r\\n    display: flex;\\r\\n    align-items: center;\\r\\n    justify-content: space-between;\\r\\n    user-select: none;\\r\\n  }\\r\\n\\r\\n  #wpCarRentalPC .crpc-time-display:hover {\\r\\n    color: #60a5fa;\\r\\n  }\\r\\n\\r\\n  #wpCarRentalPC .crpc-search-btn {\\r\\n    height: 52px;\\r\\n    width: 100%;\\r\\n    background: linear-gradient(135deg, #0b63ce 0%, #1d4ed8 100%);\\r\\n    color: #fffff