up {\\r\\n    display: flex;\\r\\n    flex-direction: column;\\r\\n    gap: 6px;\\r\\n  }\\r\\n\\r\\n  #wpCarRentalPC .crpc-dt-group label {\\r\\n    font-size: 12px;\\r\\n    color: #9ca3af;\\r\\n    font-weight: 600;\\r\\n  }\\r\\n\\r\\n  #wpCarRentalPC .crpc-dt-group input {\\r\\n    background-color: #0b0d11;\\r\\n    border: 1px solid #2f3644;\\r\\n    color: #ffffff;\\r\\n    padding: 10px 12px;\\r\\n    border-radius: 8px;\\r\\n    font-size: 14px;\\r\\n    color-scheme: dark;\\r\\n  }\\r\\n\\r\\n  #wpCarRentalPC .crpc-dt-presets {\\r\\n    display: flex;\\r\\n    align-items: center;\\r\\n    justify-content: space-between;\\r\\n    flex-wrap: wrap;\\r\\n    gap: 10px;\\r\\n    padding-top: 12px;\\r\\n    border-top: 1px solid #242934;\\r\\n  }\\r\\n\\r\\n  #wpCarRentalPC .crpc-preset-group {\\r\\n    display: flex;\\r\\n    gap: 8px;\\r\\n    flex-wrap: wrap;\\r\\n  }\\r\\n\\r\\n  #wpCarRentalPC .crpc-preset-btn {\\r\\n    background: #1e2330;\\r\\n    border: 1px solid #2f3646;\\r\\n    color: #d1d5db;\\r\\n    font-size: 12px;\\r\\n    font-weight: 600;\\r\\n    padding: 6px 12px;\\r\\n    border-radius: 6px;\\r\\n    cursor: pointer;\\r\\n    transition: all 0.15s ease;\\r\\n  }\\r\\n\\r\\n  #wpCarRentalPC .crpc-preset-btn:hover {\\r\\n    border-color: #3b82f6;\\r\\n    color: #ffffff;\\r\\n  }\\r\\n\\r\\n  #wpCarRentalPC .crpc-dt-apply {\\r\\n    background: #2563eb;\\r\\n    border: none;\\r\\n    color: #ffffff;\\r\\n    font-size: 13px;\\r\\n    font-weight: 600;\\r\\n    padding: 7px 16px;\\r\\n    border-radius: 6px;\\r\\n    cursor: pointer;\\r\\n  }\\r\\n\\r\\n  \\/* 3. Thanh t\\u00f3m t\\u1eaft k\\u1ebft qu\\u1ea3 & B\\u1ed9 l\\u1ecdc n\\u00e2ng cao *\\/\\r\\n  #wpCarRentalPC .crpc-toolbar {\\r\\n    display: flex;\\r\\n    justify-content: space-between;\\r\\n    align-items: center;\\r\\n    flex-wrap: wrap;\\r\\n    gap: 16px;\\r\\n    padding-bottom: 18px;\\r\\n    border-bottom: 1px solid #1e222b;\\r\\n    margin-bottom: 18px;\\r\\n  }\\r\