opdown g\\u1ee3i \\u00fd \\u0111\\u1ecba \\u0111i\\u1ec3m *\\/\\r\\n  #wpCarRentalPC .crpc-loc-dropdown {\\r\\n    display: none;\\r\\n    position: absolute;\\r\\n    top: calc(100% + 14px);\\r\\n    left: -12px;\\r\\n    width: 360px;\\r\\n    max-width: 90vw;\\r\\n    background-color: #161a23;\\r\\n    border: 1px solid #2d3444;\\r\\n    border-radius: 12px;\\r\\n    padding: 8px;\\r\\n    box-shadow: 0 16px 32px rgba(0, 0, 0, 0.65);\\r\\n    z-index: 50;\\r\\n    animation: crpcFadeDown 0.18s ease-out;\\r\\n  }\\r\\n\\r\\n  #wpCarRentalPC .crpc-loc-dropdown.open {\\r\\n    display: block;\\r\\n  }\\r\\n\\r\\n  #wpCarRentalPC .crpc-loc-header {\\r\\n    font-size: 11px;\\r\\n    font-weight: 700;\\r\\n    text-transform: uppercase;\\r\\n    color: #6b7280;\\r\\n    padding: 6px 10px;\\r\\n    letter-spacing: 0.5px;\\r\\n  }\\r\\n\\r\\n  #wpCarRentalPC .crpc-loc-item {\\r\\n    display: flex;\\r\\n    align-items: center;\\r\\n    gap: 10px;\\r\\n    padding: 10px;\\r\\n    border-radius: 8px;\\r\\n    cursor: pointer;\\r\\n    transition: background-color 0.15s ease;\\r\\n  }\\r\\n\\r\\n  #wpCarRentalPC .crpc-loc-item:hover {\\r\\n    background-color: #212734;\\r\\n  }\\r\\n\\r\\n  #wpCarRentalPC .crpc-loc-item-title {\\r\\n    font-size: 13px;\\r\\n    font-weight: 600;\\r\\n    color: #f3f4f6;\\r\\n  }\\r\\n\\r\\n  #wpCarRentalPC .crpc-loc-item-sub {\\r\\n    font-size: 11px;\\r\\n    color: #9ca3af;\\r\\n  }\\r\\n\\r\\n  #wpCarRentalPC .crpc-time-display {\\r\\n    font-size: 15px;\\r\\n    font-weight: 700;\\r\\n    color: #ffffff;\\r\\n    cursor: pointer;\\r\\n    display: flex;\\r\\n    align-items: center;\\r\\n    justify-content: space-between;\\r\\n    user-select: none;\\r\\n  }\\r\\n\\r\\n  #wpCarRentalPC .crpc-time-display:hover {\\r\\n    color: #60a5fa;\\r\\n  }\\r\\n\\r\\n  #wpCarRentalPC .crpc-search-btn {\\r\\n    height: 52px;\\r\\n    width: 100%;\\r\\n    background: linear-gradient(135deg, #0b63ce 0%, #1d4ed8 100%);\\r\\n    color: #ffffff;\\r\\n    border: none;\\r\\n    border-radius: 10px;\\r\\n    font-size: 16px;\\r\\n    font-weight: 700;\\r\\n    cursor: pointer;\\r\\n    display: flex;\\r\\n    align-items: center;\\r\\n    justify-content: center;\\r\\n    gap: 8px;\\r\\n    transition: transform 0.15s ease, box-shadow 0.2s ease, filter 0.2s ease;\\r\\n  }\\r\\n\\r\\n  #wpCarRentalPC .crpc-search-btn:hover {\\r\\n    filter: brightness(1.1);\\r\\n    box-shadow: 0 6px 18px rgba(11, 99, 206, 0.45);\\r\\n  }\\r\\n\\r\\n  #wpCarRentalPC .crpc-search-btn:active {\\r\\n    transform: scale(0.97);\\r\\n  }\\r\\n\\r\\n  #wpCarRentalPC .crpc-spinner {\\r\\n    width: 18px;\\r\\n    height: 18px;\\r\\n    border: 2.5px solid rgba(255, 255, 255, 0.3);\\r\\n    border-top-color: #ffffff;\\r\\n    border-radius: 50%;\\r\\n    animation: crpcSpin 0.6s linear infinite;\\r\\n    display: none;\\r\\n  }\\r\\n\\r\\n  @keyframes crpcSpin {\\r\\n    to { transform: rotate(360deg); }\\r\\n  }\\r\\n\\r\\n  @keyframes crpcFadeDown {\\r\\n    from { opacity: 0; transform: translateY(-6px); }\\r\\n    to { opacity: 1; transform: translateY(0); }\\r\\n  }\\r\\n\\r\\n  @keyframes crpcCardIn {\\r\\n    from { opacity: 0; transform: translateY(14px) scale(0.98); }\\r\\n    to { opacity: 1; transform: translateY(0) scale(1); }\\r\\n  }\\r\\n\\r\\n  \\/* Khung ch\\u1ecdn ng\\u00e0y gi\\u1edd m\\u1edf r\\u1ed9ng *\\/\\r\\n  #wpCarRentalPC .crpc-datetime-panel {\\r\\n    display: none;\\r\\n    background-color: #161a23;\\r\\n    border: 1px solid #2b313e;\\r\\n    border-radius: 12px;\\r\\n    padding: 18px;\\r\\n    margin-top: -10px;\\r\\n    margin-bottom: 22px;\\r\\n    animation: crpcFadeDown 0.2s ease-out;\\r\\n  }\\r\\n\\r\\n  #wpCarRentalPC .crpc-datetime-panel.open {\\r\\n    display: block;\\r\\n  }\\r\\n\\r\\n  #wpCarRentalPC .crpc-dt-grid {\\r\\n    display: grid;\\r\\n    grid-template-columns: repeat(2, 1fr);\\r\\n    gap: 16px;\\r\\n    margin-bottom: 14px;\\r\\n  }\\r\\n\\r\\n  #wpCarRentalPC .crpc-dt-group {\\r\\n    display: flex;\\r\\n    flex-direction: column;\\r\\n    gap: 6px;\\r\\n  }\\r\\n\\r\\n  #wpCarRentalPC .crpc-dt-group label {\\r\\n    font-size: 12px;\\r\\n    color: #9ca3af;\\r\\n    font-weight: 600;\\r\\n  }\\r\\n\\r\\n  #wpCarRentalPC .crpc-dt-group input {\\r\\n    background-color: #0b0d11;\\r\\n    border: 1px solid #2f3644;\\r\\n    color: #ffffff;\\r\\n    padding: 10px 12px;\\r\\n    border-radius: 8px;\\r\\n    font-size: 14px;\\r\\n    color-scheme: dark;\\r\\n  }\\r\\n\\r\\n  #wpCarRentalPC .crpc-dt-presets {\\r\\n    display: flex;\\r\\n    align-items: center;\\r\\n    justify-content: space-between;\\r\\n    flex-wrap: wrap;\\r\\n    gap: 10px;\\r\\n    padding-top: 12px;\\r\\n    border-top: 1px solid #242934;\\r\\n  }\\r\\n\\r\\n  #wpCarRentalPC .crpc-preset-group {\\r\\n    display: flex;\\r\\n    gap: 8px;\\r\\n    flex-wrap: wrap;\\r\\n  }\\r\\n\\r\\n  #wpCarRentalPC .crpc-preset-btn {\\r\\n    background: #1e2330;\\r\\n    border: 1px solid #2f3646;\\r\\n    color: #d1d5db;\\r\\n    font-size: 12px;\\r\\n    font-weight: 600;\\r\\n    padding: 6px 12px;\\r\\n    border-radius: 6px;\\r\\n    cursor: pointer;\\r\\n    transition: all 0.15s ease;\\r\\n  }\\r\\n\\r\\n  #wpCarRentalPC .crpc-preset-btn:hover {\\r\\n    border-color: #3b82f6;\\r\\n    color: #ffffff;\\r\\n  }\\r\\n\\r\\n  #wpCarRentalPC .crpc-dt-apply {\\r\\n    background: #2563eb;\\r\\n    border: none;\\r\\n    color: #ffffff;\\r\\n    font-size: 13px;\\r\\n    font-weight: 600;\\r\\n    padding: 7px 16px;\\r\\n    border-radius: 6px;\\r\\n    cursor: pointer;\\r\\n  }\\r\\n\\r\\n  \\/* 3. Thanh t\\u00f3m t\\u1eaft k\\u1ebft qu\\u1ea3 & B\\u1ed9 l\\u1ecdc n\\u00e2ng cao *\\/\\r\\n  #wpCarRentalPC .crpc-toolbar {\\r\\n    display: flex;\\r\\n    justify-content: space-between;\\r\\n    align-items: center;\\r\\n    flex-wrap: wrap;\\r\\n    gap: 16px;\\r\\n    padding-bottom: 18px;\\r\\n    border-bottom: 1px solid #1e222b;\\r\\n    margin-bottom: 18px;\\r\\n  }\\r\