\\n    color: #9ca3af;\\r\\n  }\\r\\n\\r\\n  #wpCarRentalPC .crpc-total-hint {\\r\\n    display: block;\\r\\n    font-size: 11px;\\r\\n    color: #9ca3af;\\r\\n    margin-top: 2px;\\r\\n  }\\r\\n\\r\\n  #wpCarRentalPC .crpc-book-btn {\\r\\n    margin-top: 14px;\\r\\n    width: 100%;\\r\\n    padding: 11px;\\r\\n    background-color: #1e2533;\\r\\n    border: 1px solid #2f394d;\\r\\n    border-radius: 8px;\\r\\n    color: #ffffff;\\r\\n    font-size: 14px;\\r\\n    font-weight: 600;\\r\\n    cursor: pointer;\\r\\n    transition: all 0.2s ease;\\r\\n  }\\r\\n\\r\\n  #wpCarRentalPC .crpc-book-btn:hover:not(:disabled) {\\r\\n    background-color: #0b63ce;\\r\\n    border-color: #0b63ce;\\r\\n    transform: translateY(-1px);\\r\\n  }\\r\\n\\r\\n  #wpCarRentalPC .crpc-book-btn:disabled {\\r\\n    background-color: #191d26;\\r\\n    border-color: #252a36;\\r\\n    color: #6b7280;\\r\\n    cursor: not-allowed;\\r\\n  }\\r\\n\\r\\n  \\/* Tr\\u1ea1ng th\\u00e1i kh\\u00f4ng t\\u00ecm th\\u1ea5y xe *\\/\\r\\n  #wpCarRentalPC .crpc-empty-state {\\r\\n    grid-column: 1 \\/ -1;\\r\\n    text-align: center;\\r\\n    padding: 48px 20px;\\r\\n    background: #13161d;\\r\\n    border: 1px dashed #2a303d;\\r\\n    border-radius: 14px;\\r\\n  }\\r\\n\\r\\n  #wpCarRentalPC .crpc-empty-state h4 {\\r\\n    font-size: 17px;\\r\\n    color: #ffffff;\\r\\n    margin: 0 0 8px 0;\\r\\n  }\\r\\n\\r\\n  #wpCarRentalPC .crpc-empty-state p {\\r\\n    font-size: 14px;\\r\\n    color: #9ca3af;\\r\\n    margin: 0 0 18px 0;\\r\\n  }\\r\\n\\r\\n  #wpCarRentalPC .crpc-reset-btn {\\r\\n    background: #2563eb;\\r\\n    color: #ffffff;\\r\\n    border: none;\\r\\n    padding: 10px 20px;\\r\\n    border-radius: 8px;\\r\\n    font-size: 14px;\\r\\n    font-weight: 600;\\r\\n    cursor: pointer;\\r\\n  }\\r\\n\\r\\n  \\/* Modal \\u0111\\u1eb7t xe *\\/\\r\\n  #wpCarRentalPC .crpc-modal-bg {\\r\\n    display: none;\\r\\n    position: fixed;\\r\\n    inset: 0;\\r\\n    background: rgba(0, 0, 0, 0.78);\\r\\n    