\\n    <\\/div>\\r\\n  <\\/div>\\r\\n\\r\\n  <!-- L\\u01b0\\u1edbi danh s\\u00e1ch xe -->\\r\\n  <div class=\\\"crpc-grid\\\" id=\\\"crpcCarGrid\\\"><\\/div>\\r\\n\\r\\n  <!-- Modal x\\u00e1c nh\\u1eadn \\u0111\\u1eb7t xe -->\\r\\n  <div class=\\\"crpc-modal-bg\\\" id=\\\"crpcModal\\\">\\r\\n    <div class=\\\"crpc-modal-box\\\">\\r\\n      <h4 class=\\\"crpc-modal-title\\\" id=\\\"crpcModalTitle\\\">\\u0110\\u1eb7t thu\\u00ea xe<\\/h4>\\r\\n      <div class=\\\"crpc-modal-info\\\" id=\\\"crpcModalInfo\\\"><\\/div>\\r\\n      <form id=\\\"crpcBookingForm\\\">\\r\\n        <input type=\\\"text\\\" class=\\\"crpc-modal-input\\\" id=\\\"crpcCustName\\\" placeholder=\\\"H\\u1ecd v\\u00e0 t\\u00ean ng\\u01b0\\u1eddi thu\\u00ea\\\" required>\\r\\n        <input type=\\\"tel\\\" class=\\\"crpc-modal-input\\\" id=\\\"crpcCustPhone\\\" placeholder=\\\"S\\u1ed1 \\u0111i\\u1ec7n tho\\u1ea1i li\\u00ean h\\u1ec7\\\" required>\\r\\n        <div class=\\\"crpc-modal-actions\\\">\\r\\n          <button type=\\\"button\\\" class=\\\"crpc-btn-cancel\\\" id=\\\"crpcModalCancel\\\">H\\u1ee7y<\\/button>\\r\\n          <button type=\\\"submit\\\" class=\\\"crpc-btn-confirm\\\">X\\u00e1c nh\\u1eadn \\u0111\\u1eb7t xe<\\/button>\\r\\n        <\\/div>\\r\\n      <\\/form>\\r\\n    <\\/div>\\r\\n  <\\/div>\\r\\n\\r\\n  <!-- Toast th\\u00f4ng b\\u00e1o -->\\r\\n  <div class=\\\"crpc-toast\\\" id=\\\"crpcToast\\\"><\\/div>\\r\\n<\\/div>\\r\\n\\r\\n<script>\\r\\n(function() {\\r\\n  const carsData = [\\r\\n    {\\r\\n      id: 1,\\r\\n      model: \'VF8\',\\r\\n      name: \'VinFast VF8\',\\r\\n      url: \'https:\\/\\/localhost\\/carrental\\/?product=vinfast-vf8\',\\r\\n      plate: \'30E-57174 \\u00b7 2023\',\\r\\n      specs: \'S\\u1ed1 t\\u1ef1 \\u0111\\u1ed9ng \\u00b7 5 ch\\u1ed7 \\u00b7 \\u0110i\\u1ec7n \\u00b7 Mi\\u1ec5n ph\\u00ed s\\u1ea1c\',\\r\\n      city: \'H\\u00e0 N\\u1ed9i\',\\r\\n      areaLabel: \'Ph\\u1ea1m H\\u00f9ng, Nam T\\u1eeb Li\\u00eam, H\\u00e0 N\\u1ed9i\',\\r\\n      lat: 21.0285,\\r\\n      lng: 105.7823,\\r\\n      areas: [\'ha noi\', \'pham hung\', \'sunshine\', \'noi bai\', \'nam tu liem\'],\\r\\n      rating: \'4.9 \\u2605 \\u00b7 12 chuy\\u1ebfn\',\\r\\n      price: 1200000,\\r\\n      sharedPrice: 350000,\\r\\n      deposit: \'C\\u00f3 th\\u1ebf ch\\u1ea5p\',\\r\\n      bookedRanges: [\\r\\n        { start: \'2026-11-19T08:00\', end: \'2026-11-21T20:00\' }\\r\\n      ],\\r\\n      image: \'https:\\/\\/localhost\\/carrental\\/wp-content\\/uploads\\/2026\\/11\\/z7591217289700_a4a4635b24059fb3a21e9a0db72192c3.jpg\'\\r\\n    },\\r\\n    {\\r\\n      id: 2,\\r\\n      model: \'VF5\',\\r\\n      name: \'VinFast VF5\',\\r\\n      plate: \'30M-99419 \\u00b7 2025\',\\r\\n      specs: \'S\\u1ed1 t\\u1ef1 \\u0111\\u1ed9ng \\u00b7 5 ch\\u1ed7 \\u00b7 \\u0110i\\u1ec7n \\u00b7 Mi\\u1ec5n ph\\u00ed s\\u1ea1c\',\\r\\n      city: \'H\\u00e0 N\\u1ed9i\',\\r\\n      areaLabel: \'C\\u1ea7u Gi\\u1ea5y, H\\u00e0 N\\u1ed9i\',\\r\\n      lat: 21.0362,\\r\\n      lng: 105.7906,\\r\\n      areas: [\'ha noi\', \'pham hung\', \'sunshine\', \'noi bai\', \'cau giay\'],\\r\\n      rating: \'5.0 \\u2605 \\u00b7 8 chuy\\u1ebfn\',\\r\\n      price: 700000,\\r\\n      sharedPrice: 220000,\\r\\n      deposit: \'C\\u00f3 th\\u1ebf ch\\u1ea5p\',\\r\\n      bookedRanges: [\\r\\n        { start: \'2026-11-18T09:00\', end: \'2026-11-19T18:00\' }\\r\\n      ],\\r\\n      image: \'https:\\/\\/localhost\\/carrental\\/wp-content\\/uploads\\/2026\\/11\\/z7748766438181_aa63553d38ac827c5dd912f083c8e206.jpg\'\\r\\n    },\\r\\n    {\\r\\n      id: 3,\\r\\n      model: \'VF3\',\\r\\n      name: \'VinFast VF3\',\\r\\n      plate: \'30B-10522 \\u00b7 2024\',\\r\\n      specs: \'S\\u1ed1 t\\u1ef1 \\u0111\\u1ed9ng \\u00b7 4 ch\\u1ed7 \\u00b7 \\u0110i\\u1ec7n \\u00b7 Mi\\u1ec5n ph\\u00ed s\\u1ea1c\',\\r\\n      city: \'H\\u00e0 N\\u1ed9i\',\\r\\n      areaLabel: \'\\u0110\\u1ed1ng \\u0110a, H\\u00e0 N\\u1ed9i\',\\r\\n      lat: 21.0152,\\r\\n      lng: 105.8291,\\r\\n      areas: [\'ha noi\', \'pham hung\', \'sunshine\', \'noi bai\', \'dong da\'],\\r\\n      rating: \'4.8 \\u2605 \\u00b7 19 chuy\\u1ebfn\',\\r\\n      price: 480000,\\r\\n      sharedPrice: 150000,\\r\\n      deposit: \'C\\u00f3 th\\u1ebf ch\\u1ea5p\',\\r\\n      bookedRanges: [],\\r\\n      image: \'https:\\/\\/localhost\\/carrental\\/wp-content\\/uploads\\/2026\\/11\\/z7591217297154_79e55258161d7a4c58221a7fd5e82ba9.jpg\'\\r\\n    },\\r\\n    {\\r\\n      id: 4,\\r\\n      model: \'VF3\',\\r\\n      name: \'VinFast VF3 Special Edition\',\\r\\n      plate: \'30L-33122 \\u00b7 2024\',\\r\\n      specs: \'S\\u1ed1 t\\u1ef1 \\u0111\\u1ed9ng \\u00b7 5 ch\\u1ed7 \\u00b7 \\u0110i\\u1ec7n \\u00b7 Mi\\u1ec5n ph\\u00ed s\\u1ea1c\',\\r\\n      city: \'TP. H\\u1ed3 Ch\\u00ed Minh\',\\r\\n      areaLabel: \'Qu\\u1eadn 1, TP. H\\u1ed3 Ch\\u00ed Minh\',\\r\\n      lat: 10.7769,\\r\\n      lng: 106.7009,\\r\\n      areas: [\'ho chi minh\', \'quan 1\', \'ben thanh\', \'tan son nhat\', \'sai gon\'],\\r\\n      rating: \'4.9 \\u2605 \\u00b7 15 chuy\\u1ebfn\',\\r\\n      price: 1250000,\\r\\n      sharedPrice: 380000,\\r\\n      deposit: \'C\\u00f3 th\\u1ebf ch\\u1ea5p\',\\r\\n      bookedRanges: [],\\r\\n      image: \'https:\\/\\/localhost\\/carrental\\/wp-content\\/uploads\\/2026\\/11\\/z7591217300331_344cbad2afbc83753f1e027cc1adb1f0.jpg\'\\r\\n    },\\r\\n    {\\r\\n      id: 5,\\r\\n      model: \'VF3\',\\r\\n      name: \'VinFast VF3 Gold\',\\r\\n      plate: \'14A-93700 \\u00b7 2024\',\\r\\n      specs: \'S\\u1ed1 t\\u1ef1 \\u0111\\u1ed9ng \\u00b7 5 ch\\u1ed7 \\u00b7 \\u0110i\\u1ec7n \\u00b7 Mi\\u1ec5n ph\\u00ed s\\u1ea1c\',\\r\\n      city: \'\\u0110\\u00e0 N\\u1eb5ng\',\\r\\n      areaLabel: \'H\\u1ea3i Ch\\u00e2u, \\u0110\\u00e0 N\\u1eb5ng\',\\r\\n      lat: 16.0544,\\r\\n      lng: 108.2022,\\r\\n      areas: [\'da nang\', \'hai chau\', \'san bay\'],\\r\\n      rating: \'5.0 \\u2605 \\u00b7 6 chuy\\u1ebfn\',\\r\\n      price: 680000,\\r\\n      sharedPrice: 200000,\\r\\n      deposit: \'C\\u00f3 th\\u1ebf ch\\u1ea5p\',\\r\\n      bookedRanges: [],\\r\\n      image: \'https:\\/\\/localhost\\/carrental\\/wp-content\\/uploads\\/2026\\/11\\/z7591217291046_369c935f164de99786969e28c55f3c26.jpg\'\\r\\n    }\\r\\n  ];\\r\\n\\r\\n  let selectedMode = \'T\\u1ef1 l\\u00e1i\';\\r\\n  let selectedModel = \'ALL\';\\r\\n  let rentalDays = 1;\\r\\n  let activeCar = null;\\r\\n  let toastTimer = null;\\r\\n\\r\\n  \\/\\/ Tr\\u1ea1ng th\\u00e1i t\\u1ecda \\u0111\\u1ed9 & v\\u1ecb tr\\u00ed hi\\u1ec7n t\\u1ea1i c\\u1ee7a kh\\u00e1ch\\r\\n  let userCoords = null;\\r\\n  let isUsingGPS = false;\\r\\n\\r\\n  const gridEl = document.getElementById(\'crpcCarGrid\');\\r\\n  const locInput = document.getElementById(\'crpcLocationInput\');\\r\\n  const clearLocBtn = document.getElementById(\'crpcClearLoc\');\\r\\n  const locDropdown = document.getElementById(\'crpcLocDropdown\');\\r\\n  const gpsBtn = document.getElementById(\'crpcGpsBtn\');\\r\\n  const gpsBtnLabel = document.getElementById(\'crpcGpsBtnLabel\');\\r\\n  const statusTextEl = document.getElementById(\'crpcLocationStatusText\');\\r\\n  const startInput = document.getElementById(\'crpcStartDt\');\\r\\n  const endInput = document.getElementById(\'crpcEndDt\');\\r\\n  const timeDisplay = document.getElementById(\'crpcTimeDisplay\');\\r\\n  const dtPanel = document.getElementById(\'crpcDatetimePanel\');\\r\\n  const summaryLoc = document.getElementById(\'crpcSummaryLoc\');\\r\\n  const summaryTime = document.getElementById(\'crpcSummaryTime\');\\r\\n  const resultCountEl = document.getElementById(\'crpcResultCount\');\\r\\n  const keywordInput = document.getElementById(\'crpcKeywordInput\');\\r\\n  const onlyAvailCheckbox = document.getElementById(\'crpcOnlyAvail\');\\r\\n  const sortSelect = document.getElementById(\'crpcSortSelect\');\\r\\n  const modalEl = document.getElementById(\'crpcModal\');\\r\\n  const toastEl = document.getElementById(\'crpcToast\');\\r\\n\\r\\n  function removeAccents(str) {\\r\\n    return str\\r\\n      .normalize(\'NFD\')\\r\\n      .replace(\\/[\\\\u0300-\\\\u036f]\\/g, \'\')\\r\\n      .replace(\\/\\u0111\\/g, \'d\')\\r\\n      .replace(\\/\\u0110\\/g, \'D\')\\r\\n      .toLowerCase()\\r\\n      .trim();\\r\\n  }\\r\\n\\r\\n  function showToast(msg, isError = false) {\\r\\n    toastEl.textContent = msg;\\r\\n    toastEl.style.borderLeftColor = isError ? \'#d9383a\' : \'#10b981\';\\r\\n    toastEl.classList.add(\'show\');\\r\\n    clearTimeout(toastTimer);\\r\\n    toastTimer = setTimeout(() => {\\r\\n      toastEl.classList.remove(\'show\');\\r\\n    }, 4200);\\r\\n  }\\r\\n\\r\\n  \\/\\/ T\\u00ednh kho\\u1ea3ng c\\u00e1ch (km) gi\\u1eefa t\\u1ecda \\u0111\\u1ed9 kh\\u00e1ch v\\u00e0 xe\\r\\n  function calculateDistanceKm(lat1, lon1, lat2, lon2) {\\r\\n    const R = 6371;\\r\\n    const dLat = (lat2 - lat1) * Math.PI \\/ 180;\\r\\n    const dLon = (lon2 - lon1) * Math.PI \\/ 180;\\r\\n    const a =\\r\\n      Math.sin(dLat \\/ 2) * Math.sin(dLat \\/ 2) +\\r\\n      Math.cos(lat1 * Math.PI \\/ 180) * Math.cos(lat2 * Math.PI \\/ 180) *\\r\\n      Math.sin(dLon \\/ 2) * Math.sin(dLon \\/ 2);\\r\\n    const c = 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1 - a));\\r\\n    return R * c;\\r\\n  }\\r\\n\\r\\n  function formatDistanceLabel(km) {\\r\\n    if (km < 1) return `${Math.round(km * 1000)} m`;\\r\\n    if (km < 50) return `${km.toFixed(1)} km`;\\r\\n    return `${Math.round(km)} km`;\\r\\n  }\\r\\n\\r\\n  \\/\\/ L\\u1ea5y v\\u1ecb tr\\u00ed hi\\u1ec7n t\\u1ea1i c\\u1ee7a kh\\u00e1ch b\\u1eb1ng Geolocation API + D\\u1ecbch \\u0111\\u1ecba ch\\u1ec9 ti\\u1ebfng Vi\\u1ec7t\\r\\n  function detectCustomerLocation(isManualClick = false) {\\r\\n    if (!navigator.geolocation) {\\r\\n      locInput.value = \'Sunshine Center, 16 Ph\\u1ea1m H\\u00f9ng, H\\u00e0 N\\u1ed9i\';\\r\\n      toggleClearButton();\\r\\n      updateSearchSummary();\\r\\n      renderCars();\\r\\n      if (isManualClick) showToast(\'Tr\\u00ecnh duy\\u1ec7t c\\u1ee7a b\\u1ea1n kh\\u00f4ng h\\u1ed7 tr\\u1ee3 \\u0111\\u1ecbnh v\\u1ecb GPS.\', true);\\r\\n      return;\\r\\n    }\\r\\n\\r\\n    gpsBtn.classList.add(\'is-locating\');\\r\\n    gpsBtnLabel.textContent = \'\\u0110ang \\u0111\\u1ecbnh v\\u1ecb...\';\\r\\n    statusTextEl.textContent = \'\\u0110ang x\\u00e1c \\u0111\\u1ecbnh v\\u1ecb tr\\u00ed hi\\u1ec7n t\\u1ea1i c\\u1ee7a b\\u1ea1n...\';\\r\\n\\r\\n    navigator.geolocation.getCurrentPosition(\\r\\n      async (position) => {\\r\\n        const lat = position.coords.latitude;\\r\\n        const lng = position.coords.longitude;\\r\\n        userCoords = { lat, lng };\\r\\n        isUsingGPS = true;\\r\\n\\r\\n        let resolvedAddress = `V\\u1ecb tr\\u00ed hi\\u1ec7n t\\u1ea1i (${lat.toFixed(4)}, ${lng.toFixed(4)})`;\\r\\n\\r\\n        try {\\r\\n          const res = await fetch(\\r\\n            `https:\\/\\/nominatim.openstreetmap.org\\/reverse?format=jsonv2&lat=${lat}&lon=${lng}&accept-language=vi`\\r\\n          );\\r\\n          if (res.ok) {\\r\\n            const data = await res.json();\\r\\n            const addr = data.address || {};\\r\\n            const parts = [\\r\\n              addr.road || addr.pedestrian || addr.suburb,\\r\\n              addr.quarter || addr.city_district || addr.district || addr.county,\\r\\n              addr.city || addr.state || addr.town\\r\\n            ].filter(Boolean);\\r\\n\\r\\n            if (parts.length > 0) {\\r\\n              resolvedAddress = parts.join(\', \');\\r\\n            } else if (data.display_name) {\\r\\n              resolvedAddress = data.display_name.split(\',\').slice(0, 3).join(\',\');\\r\\n            }\\r\\n          }\\r\\n        } catch (err) {\\r\\n          \\/\\/ Gi\\u1eef fallback t\\u1ecda \\u0111\\u1ed9 n\\u1ebfu m\\u1ea1ng ch\\u1eb7n API d\\u1ecbch \\u0111\\u1ecba ch\\u1ec9\\r\\n        }\\r\\n\\r\\n        locInput.value = resolvedAddress;\\r\\n        gpsBtn.classList.remove(\'is-locating\');\\r\\n        gpsBtnLabel.textContent = \'\\u0110\\u00e3 \\u0111\\u1ecbnh v\\u1ecb\';\\r\\n        statusTextEl.textContent = `\\u0110ang hi\\u1ec3n th\\u1ecb xe g\\u1ea7n: ${resolvedAddress}`;\\r\\n        sortSelect.value = \'nearest\';\\r\\n\\r\\n        toggleClearButton();\\r\\n        updateSearchSummary();\\r\\n        renderCars();\\r\\n\\r\\n        if (isManualClick) {\\r\\n          showToast(`\\u0110\\u00e3 c\\u1eadp nh\\u1eadt v\\u1ecb tr\\u00ed hi\\u1ec7n t\\u1ea1i: ${resolvedAddress}`);\\r\\n        }\\r\\n      },\\r\\n      (error) => {\\r\\n        gpsBtn.classList.remove(\'is-locating\');\\r\\n        gpsBtnLabel.textContent = \'V\\u1ecb tr\\u00ed hi\\u1ec7n t\\u1ea1i\';\\r\\n        isUsingGPS = false;\\r\\n\\r\\n        if (locInput.value === \'\\u0110ang x\\u00e1c \\u0111\\u1ecbnh v\\u1ecb tr\\u00ed c\\u1ee7a b\\u1ea1n...\') {\\r\\n          locInput.value = \'\';\\r\\n        }\\r\\n        statusTextEl.textContent = \'Ch\\u01b0a b\\u1eadt GPS \\u00b7 Hi\\u1ec3n th\\u1ecb t\\u1ea5t c\\u1ea3 xe s\\u1eb5n c\\u00f3\';\\r\\n        toggleClearButton();\\r\\n        updateSearchSummary();\\r\\n        renderCars();\\r\\n\\r\\n        if (isManualClick) {\\r\\n          showToast(\'Kh\\u00f4ng th\\u1ec3 truy c\\u1eadp v\\u1ecb tr\\u00ed. Vui l\\u00f2ng cho ph\\u00e9p quy\\u1ec1n V\\u1ecb tr\\u00ed tr\\u00ean tr\\u00ecnh duy\\u1ec7t ho\\u1eb7c nh\\u1eadp tay \\u0111\\u1ecba \\u0111i\\u1ec3m.\', true);\\r\\n        }\\r\\n      },\\r\\n      { enableHighAccuracy: true, timeout: 8000, maximumAge: 60000 }\\r\\n    );\\r\\n  }\\r\\n\\r\\n  function formatVNShort(dateStr) {\\r\\n    const d = new Date(dateStr);\\r\\n    if (isNaN(d.getTime())) return \'\';\\r\\n    const days = [\'CN\', \'T2\', \'T3\', \'T4\', \'T5\', \'T6\', \'T7\'];\\r\\n    const pad = n => String(n).padStart(2, \'0\');\\r\\n    return `${pad(d.getHours())}:${pad(d.getMinutes())} ${days[d.getDay()]}, ${pad(d.getDate())}\\/${pad(d.getMonth() + 1)}`;\\r\\n  }\\r\\n\\r\\n  function isCarBooked(car) {\\r\\n    const reqStart = new Date(startInput.value).getTime();\\r\\n    const reqEnd = new Date(endInput.value).getTime();\\r\\n    if (isNaN(reqStart) || isNaN(reqEnd)) return false;\\r\\n\\r\\n    return car.bookedRanges.some(range => {\\r\\n      const bStart = new Date(range.start).getTime();\\r\\n      const bEnd = new Date(range.end).getTime();\\r\\n      return reqStart < bEnd && reqEnd > bStart;\\r\\n    });\\r\\n  }\\r\\n\\r\\n  function updateSearchSummary() {\\r\\n    const s = new Date(startInput.value);\\r\\n    const e = new Date(endInput.value);\\r\\n    if (e <= s) {\\r\\n      const nextDay = new Date(s.getTime() + 24 * 60 * 60 * 1000);\\r\\n      const pad = n => String(n).padStart(2, \'0\');\\r\\n      endInput.value = `${nextDay.getFullYear()}-${pad(nextDay.getMonth() + 1)}-${pad(nextDay.getDate())}T${pad(nextDay.getHours())}:${pad(nextDay.getMinutes())}`;\\r\\n    }\\r\\n\\r\\n    const validEnd = new Date(endInput.value);\\r\\n    const diffMs = validEnd - s;\\r\\n    rentalDays = Math.max(1, Math.ceil(diffMs \\/ (1000 * 60 * 60 * 24)));\\r\\n\\r\\n    const formattedRange = `${formatVNShort(startInput.value)} - ${formatVNShort(endInput.value)}`;\\r\\n    timeDisplay.querySelector(\'span\').textContent = formattedRange;\\r\\n    const rawLoc = locInput.value.trim();\\r\\n    summaryLoc.textContent = (rawLoc && rawLoc !== \'\\u0110ang x\\u00e1c \\u0111\\u1ecbnh v\\u1ecb tr\\u00ed c\\u1ee7a b\\u1ea1n...\') ? rawLoc : \'T\\u1ea5t c\\u1ea3 khu v\\u1ef1c\';\\r\\n    summaryTime.textContent = `${formattedRange} \\u00b7 ${rentalDays} ng\\u00e0y \\u00b7 ${selectedMode}`;\\r\\n  }\\r\\n\\r\\n  function getActivePrice(car) {\\r\\n    return selectedMode === \'Thu\\u00ea xe gh\\u00e9p\' ? car.sharedPrice : car.price;\\r\\n  }\\r\\n\\r\\n  function renderCars() {\\r\\n    const rawLoc = locInput.value.trim();\\r\\n    const locQuery = (rawLoc && rawLoc !== \'\\u0110ang x\\u00e1c \\u0111\\u1ecbnh v\\u1ecb tr\\u00ed c\\u1ee7a b\\u1ea1n...\') ? removeAccents(rawLoc) : \'\';\\r\\n    const kwQuery = removeAccents(keywordInput.value);\\r\\n    const onlyAvail = onlyAvailCheckbox.checked;\\r\\n    const sortBy = sortSelect.value;\\r\\n\\r\\n    \\/\\/ T\\u00ednh kho\\u1ea3ng c\\u00e1ch cho t\\u1eebng xe n\\u1ebfu \\u0111\\u00e3 c\\u00f3 t\\u1ecda \\u0111\\u1ed9 kh\\u00e1ch\\r\\n    const carsWithDist = carsData.map(car => {\\r\\n      const distanceKm = userCoords\\r\\n        ? calculateDistanceKm(userCoords.lat, userCoords.lng, car.lat, car.lng)\\r\\n        : null;\\r\\n      return { ...car, distanceKm };\\r\\n    });\\r\\n\\r\\n    let filtered = carsWithDist.filter(car => {\\r\\n      if (selectedModel !== \'ALL\' && car.model !== selectedModel) return false;\\r\\n\\r\\n      \\/\\/ N\\u1ebfu kh\\u00e1ch g\\u00f5 tay \\u0111\\u1ecba \\u0111i\\u1ec3m (kh\\u00f4ng d\\u00f9ng GPS) th\\u00ec l\\u1ecdc theo khu v\\u1ef1c\\r\\n      if (!isUsingGPS && locQuery) {\\r\\n        const cityMatch = removeAccents(car.city).includes(locQuery) || locQuery.includes(removeAccents(car.city));\\r\\n        const areaMatch = car.areas.some(a => locQuery.includes(a) || a.includes(locQuery));\\r\\n        if (!cityMatch && !areaMatch) return false;\\r\\n      }\\r\\n\\r\\n      if (kwQuery) {\\r\\n        const haystack = removeAccents(`${car.name} ${car.plate} ${car.specs} ${car.city} ${car.areaLabel}`);\\r\\n        if (!haystack.includes(kwQuery)) return false;\\r\\n      }\\r\\n\\r\\n      if (onlyAvail && isCarBooked(car)) return false;\\r\\n\\r\\n      return true;\\r\\n    });\\r\\n\\r\\n    \\/\\/ S\\u1eafp x\\u1ebfp theo l\\u1ef1a ch\\u1ecdn\\r\\n    if (sortBy === \'nearest\' && userCoords) {\\r\\n      filtered.sort((a, b) => a.distanceKm - b.distanceKm);\\r\\n    } else if (sortBy === \'price-asc\') {\\r\\n      filtered.sort((a, b) => getActivePrice(a) - getActivePrice(b));\\r\\n    } else if (sortBy === \'price-desc\') {\\r\\n      filtered.sort((a, b) => getActivePrice(b) - getActivePrice(a));\\r\\n    }\\r\\n\\r\\n    resultCountEl.textContent = `T\\u00ecm th\\u1ea5y ${filtered.length} xe`;\\r\\n\\r\\n    if (filtered.length === 0) {\\r\\n      gridEl.innerHTML = `\\r\\n        <div class=\\\"crpc-empty-state\\\">\\r\\n          <h4>Kh\\u00f4ng t\\u00ecm th\\u1ea5y xe ph\\u00f9 h\\u1ee3p v\\u1edbi \\u0111i\\u1ec1u ki\\u1ec7n t\\u00ecm ki\\u1ebfm<\\/h4>\\r\\n          <p>Th\\u1eed b\\u1ea5m \\\"V\\u1ecb tr\\u00ed hi\\u1ec7n t\\u1ea1i\\\" \\u0111\\u1ec3 t\\u00ecm xe g\\u1ea7n b\\u1ea1n nh\\u1ea5t ho\\u1eb7c x\\u00f3a b\\u1edbt b\\u1ed9 l\\u1ecdc hi\\u1ec7n t\\u1ea1i.<\\/p>\\r\\n          <button type=\\\"button\\\" class=\\\"crpc-reset-btn\\\" id=\\\"crpcResetAllBtn\\\">Hi\\u1ec3n th\\u1ecb t\\u1ea5t c\\u1ea3 xe<\\/button>\\r\\n        <\\/div>\\r\\n      `;\\r\\n      document.getElementById(\'crpcResetAllBtn\').addEventListener(\'click\', () => {\\r\\n        locInput.value = \'\';\\r\\n        keywordInput.value = \'\';\\r\\n        selectedModel = \'ALL\';\\r\\n        isUsingGPS = false;\\r\\n        onlyAvailCheckbox.checked = false;\\r\\n        clearLocBtn.style.display = \'none\';\\r\\n        document.querySelectorAll(\'#wpCarRentalPC .crpc-filter-btn\').forEach(b => {\\r\\n          b.classList.toggle(\'active\', b.getAttribute(\'data-model\') === \'ALL\');\\r\\n        });\\r\\n        updateSearchSummary();\\r\\n        renderCars();\\r\\n      });\\r\\n      return;\\r\\n    }\\r\\n\\r\\n    gridEl.innerHTML = filtered.map((car, index) => {\\r\\n      const booked = isCarBooked(car);\\r\\n      const unitPrice = getActivePrice(car);\\r\\n      const totalPrice = (unitPrice * rentalDays).toLocaleString(\'vi-VN\');\\r\\n      const unitLabel = selectedMode === \'Thu\\u00ea xe gh\\u00e9p\' ? \'\\/gh\\u1ebf\\/ng\\u00e0y\' : \'\\/ng\\u00e0y\';\\r\\n      const distanceHtml = car.distanceKm !== null\\r\\n        ? `<span class=\\\"crpc-dist-tag\\\">C\\u00e1ch b\\u1ea1n ~${formatDistanceLabel(car.distanceKm)}<\\/span>`\\r\\n        : \'\';\\r\\n\\r\\n      return `\\r\\n        <div class=\\\"crpc-card ${booked ? \'is-booked\' : \'\'}\\\" style=\\\"animation-delay: ${index * 0.06}s\\\">\\r\\n          <div class=\\\"crpc-card-img-wrap\\\">\\r\\n            <img src=\\\"${car.image}\\\" alt=\\\"${car.name}\\\" onerror=\\\"this.src=\'data:image\\/svg+xml;utf8,<svg xmlns=%22http:\\/\\/www.w3.org\\/2000\\/svg%22 width=%22400%22 height=%22200%22><rect width=%22100%25%22 height=%22100%25%22 fill=%22%23f3f4f6%22\\/><text x=%2250%25%22 y=%2250%25%22 dominant-baseline=%22middle%22 text-anchor=%22middle%22 fill=%22%236b7280%22 font-family=%22sans-serif%22 font-size=%2218%22>${car.name}<\\/text><\\/svg>\'\\\">\\r\\n            <span class=\\\"crpc-avail-tag ${booked ? \'busy\' : \'ready\'}\\\">\\r\\n              ${booked ? \'\\u0110\\u00e3 k\\u00edn l\\u1ecbch gi\\u1edd n\\u00e0y\' : \'\\u25cf S\\u1eb5n s\\u00e0ng giao xe\'}\\r\\n            <\\/span>\\r\\n            ${distanceHtml}\\r\\n          <\\/div>\\r\\n          <div class=\\\"crpc-card-body\\\">\\r\\n            <div class=\\\"crpc-badge\\\">\\r\\n              <svg viewBox=\\\"0 0 24 24\\\"><path d=\\\"M12 22s8-4 8-10V5l-8-3-8 3v7c0 6 8 10 8 10z\\\"\\/><\\/svg>\\r\\n              ${car.deposit}\\r\\n            <\\/div>\\r\\n            <h3 class=\\\"crpc-car-name\\\">${car.name}<\\/h3>\\r\\n            <p class=\\\"crpc-car-plate\\\">Bi\\u1ec3n s\\u1ed1: ${car.plate}<\\/p>\\r\\n            <p class=\\\"crpc-car-specs\\\">${car.specs}<\\/p>\\r\\n            <div class=\\\"crpc-car-loc\\\">\\r\\n              <svg viewBox=\\\"0 0 24 24\\\"><path d=\\\"M21 10c0 7-9 13-9 13s-9-6-9-13a9 9 0 0 1 18 0z\\\"\\/><circle cx=\\\"12\\\" cy=\\\"10\\\" r=\\\"3\\\"\\/><\\/svg>\\r\\n              <span>${car.areaLabel}<\\/span>\\r\\n            <\\/div>\\r\\n            <div class=\\\"crpc-card-footer\\\">\\r\\n              <span class=\\\"crpc-rating\\\">${car.rating}<\\/span>\\r\\n              <div class=\\\"crpc-price-box\\\">\\r\\n                <span class=\\\"crpc-price\\\">${unitPrice.toLocaleString(\'vi-VN\')}\\u0111<\\/span>\\r\\n                <span class=\\\"crpc-price-unit\\\">${unitLabel}<\\/span>\\r\\n                <span class=\\\"crpc-total-hint\\\">T\\u1ed5ng ${rentalDays} ng\\u00e0y: <strong>${totalPrice}\\u0111<\\/strong><\\/span>\\r\\n              <\\/div>\\r\\n            <\\/div>\\r\\n            <button type=\\\"button\\\" class=\\\"crpc-book-btn\\\" data-id=\\\"${car.id}\\\" ${booked ? \'disabled\' : \'\'}>\\r\\n              ${booked ? \'K\\u00edn l\\u1ecbch trong khung gi\\u1edd ch\\u1ecdn\' : \'Ch\\u1ecdn thu\\u00ea xe n\\u00e0y\'}\\r\\n            <\\/button>\\r\\n          <\\/div>\\r\\n        <\\/div>\\r\\n      `;\\r\\n    }).join(\'\');\\r\\n\\r\\n    gridEl.querySelectorAll(\'.crpc-book-btn:not(:disabled)\').forEach(btn => {\\r\\n      btn.addEventListener(\'click\', function() {\\r\\n        const carId = Number(this.getAttribute(\'data-id\'));\\r\\n        activeCar = filtered.find(c => c.id === carId);\\r\\n        if (!activeCar) return;\\r\\n\\r\\n        const unitPrice = getActivePrice(activeCar);\\r\\n        const total = (unitPrice * rentalDays).toLocaleString(\'vi-VN\');\\r\\n        const distInfo = activeCar.distanceKm !== null ? ` (C\\u00e1ch b\\u1ea1n ~${formatDistanceLabel(activeCar.distanceKm)})` : \'\';\\r\\n        document.getElementById(\'crpcModalTitle\').textContent = `\\u0110\\u1eb7t xe ${activeCar.name}`;\\r\\n        document.getElementById(\'crpcModalInfo\').innerHTML = `\\r\\n          <strong>H\\u00ecnh th\\u1ee9c:<\\/strong> ${selectedMode}<br>\\r\\n          <strong>Bi\\u1ec3n s\\u1ed1:<\\/strong> ${activeCar.plate}<br>\\r\\n          <strong>\\u0110i\\u1ec3m nh\\u1eadn xe:<\\/strong> ${locInput.value.trim() || activeCar.areaLabel}${distInfo}<br>\\r\\n          <strong>Th\\u1eddi gian:<\\/strong> ${timeDisplay.querySelector(\'span\').textContent} (${rentalDays} ng\\u00e0y)<br>\\r\\n          <strong>T\\u1ed5ng t\\u1ea1m t\\u00ednh:<\\/strong> <span style=\\\"color:#d9383a; font-weight:700; font-size:15px;\\\">${total}\\u0111<\\/span>\\r\\n        `;\\r\\n        modalEl.classList.add(\'open\');\\r\\n      });\\r\\n    });\\r\\n  }\\r\\n\\r\\n  function triggerSearchWithEffect() {\\r\\n    const spinner = document.getElementById(\'crpcSpinner\');\\r\\n    const btnText = document.getElementById(\'crpcSearchBtnText\');\\r\\n\\r\\n    dtPanel.classList.remove(\'open\');\\r\\n    locDropdown.classList.remove(\'open\');\\r\\n    gridEl.classList.add(\'is-loading\');\\r\\n    spinner.style.display = \'inline-block\';\\r\\n    btnText.textContent = \'\\u0110ang t\\u00ecm...\';\\r\\n\\r\\n    setTimeout(() => {\\r\\n      updateSearchSummary();\\r\\n      renderCars();\\r\\n      gridEl.classList.remove(\'is-loading\');\\r\\n      spinner.style.display = \'none\';\\r\\n      btnText.textContent = \'T\\u00ecm xe\';\\r\\n    }, 320);\\r\\n  }\\r\\n\\r\\n  function toggleClearButton() {\\r\\n    const val = locInput.value.trim();\\r\\n    clearLocBtn.style.display = (val && val !== \'\\u0110ang x\\u00e1c \\u0111\\u1ecbnh v\\u1ecb tr\\u00ed c\\u1ee7a b\\u1ea1n...\') ? \'flex\' : \'none\';\\r\\n  }\\r\\n\\r\\n  \\/\\/ S\\u1ef1 ki\\u1ec7n n\\u00fat \\u0111\\u1ecbnh v\\u1ecb GPS\\r\\n  gpsBtn.addEventListener(\'click\', (e) => {\\r\\n    e.stopPropagation();\\r\\n    locDropdown.classList.remove(\'open\');\\r\\n    detectCustomerLocation(true);\\r\\n  });\\r\\n\\r\\n  document.getElementById(\'crpcDropdownGps\').addEventListener(\'click\', () => {\\r\\n    locDropdown.classList.remove(\'open\');\\r\\n    detectCustomerLocation(true);\\r\\n  });\\r\\n\\r\\n  locInput.addEventListener(\'focus\', () => {\\r\\n    locDropdown.classList.add(\'open\');\\r\\n  });\\r\\n\\r\\n  locInput.addEventListener(\'input\', () => {\\r\\n    isUsingGPS = false;\\r\\n    userCoords = null;\\r\\n    gpsBtnLabel.textContent = \'V\\u1ecb tr\\u00ed hi\\u1ec7n t\\u1ea1i\';\\r\\n    toggleClearButton();\\r\\n    updateSearchSummary();\\r\\n    renderCars();\\r\\n  });\\r\\n\\r\\n  clearLocBtn.addEventListener(\'click\', () => {\\r\\n    locInput.value = \'\';\\r\\n    isUsingGPS = false;\\r\\n    userCoords = null;\\r\\n    gpsBtnLabel.textContent = \'V\\u1ecb tr\\u00ed hi\\u1ec7n t\\u1ea1i\';\\r\\n    statusTextEl.textContent = \'Hi\\u1ec3n th\\u1ecb t\\u1ea5t c\\u1ea3 khu v\\u1ef1c\';\\r\\n    toggleClearButton();\\r\\n    locInput.focus();\\r\\n    updateSearchSummary();\\r\\n    renderCars();\\r\\n  });\\r\\n\\r\\n  document.querySelectorAll(\'#wpCarRentalPC .crpc-loc-item\').forEach(item => {\\r\\n    item.addEventListener(\'click\', function() {\\r\\n      locInput.value = this.getAttribute(\'data-val\');\\r\\n      const lat = parseFloat(this.getAttribute(\'data-lat\'));\\r\\n      const lng = parseFloat(this.getAttribute(\'data-lng\'));\\r\\n      userCoords = (!isNaN(lat) && !isNaN(lng)) ? { lat, lng } : null;\\r\\n      isUsingGPS = false;\\r\\n      gpsBtnLabel.textContent = \'V\\u1ecb tr\\u00ed hi\\u1ec7n t\\u1ea1i\';\\r\\n      statusTextEl.textContent = `\\u0110ang xem xe quanh: ${locInput.value}`;\\r\\n      sortSelect.value = \'nearest\';\\r\\n      toggleClearButton();\\r\\n      locDropdown.classList.remove(\'open\');\\r\\n      triggerSearchWithEffect();\\r\\n    });\\r\\n  });\\r\\n\\r\\n  document.addEventListener(\'click\', (e) => {\\r\\n    if (!e.target.closest(\'#wpCarRentalPC .crpc-field\')) {\\r\\n      locDropdown.classList.remove(\'open\');\\r\\n    }\\r\\n  });\\r\\n\\r\\n  document.querySelectorAll(\'#wpCarRentalPC .crpc-tab-btn\').forEach(btn => {\\r\\n    btn.addEventListener(\'click\', function() {\\r\\n      document.querySelectorAll(\'#wpCarRentalPC .crpc-tab-btn\').forEach(b => b.classList.remove(\'active\'));\\r\\n      this.classList.add(\'active\');\\r\\n      selectedMode = this.getAttribute(\'data-mode\');\\r\\n      updateSearchSummary();\\r\\n      renderCars();\\r\\n    });\\r\\n  });\\r\\n\\r\\n  document.querySelectorAll(\'#wpCarRentalPC .crpc-filter-btn\').forEach(btn => {\\r\\n    btn.addEventListener(\'click\', function() {\\r\\n      document.querySelectorAll(\'#wpCarRentalPC .crpc-filter-btn\').forEach(b => b.classList.remove(\'active\'));\\r\\n      this.classList.add(\'active\');\\r\\n      selectedModel = this.getAttribute(\'data-model\');\\r\\n      renderCars();\\r\\n    });\\r\\n  });\\r\\n\\r\\n  keywordInput.addEventListener(\'input\', renderCars);\\r\\n  onlyAvailCheckbox.addEventListener(\'change\', renderCars);\\r\\n  sortSelect.addEventListener(\'change\', renderCars);\\r\\n\\r\\n  timeDisplay.addEventListener(\'click\', () => {\\r\\n    dtPanel.classList.toggle(\'open\');\\r\\n  });\\r\\n\\r\\n  document.querySelectorAll(\'#wpCarRentalPC .crpc-preset-btn\').forEach(btn => {\\r\\n    btn.addEventListener(\'click\', function() {\\r\\n      const addDays = Number(this.getAttribute(\'data-days\'));\\r\\n      const start = new Date(startInput.value);\\r\\n      if (isNaN(start.getTime())) return;\\r\\n      const end = new Date(start.getTime() + addDays * 24 * 60 * 60 * 1000);\\r\\n      const pad = n => String(n).padStart(2, \'0\');\\r\\n      endInput.value = `${end.getFullYear()}-${pad(end.getMonth() + 1)}-${pad(end.getDate())}T${pad(end.getHours())}:${pad(end.getMinutes())}`;\\r\\n      updateSearchSummary();\\r\\n    });\\r\\n  });\\r\\n\\r\\ndocument.getElementById(\'crpcBookingForm\').addEventListener(\'submit\', async function(e) {\\r\\n    e.preventDefault();\\r\\n    const name = document.getElementById(\'crpcCustName\').value.trim();\\r\\n    const phone = document.getElementById(\'crpcCustPhone\').value.trim();\\r\\n    const submitBtn = this.querySelector(\'.crpc-btn-confirm\');\\r\\n\\r\\n    const unitPrice = getActivePrice(activeCar);\\r\\n    const total = (unitPrice * rentalDays).toLocaleString(\'vi-VN\') + \'\\u0111\';\\r\\n    const rentTimeText = `${timeDisplay.querySelector(\'span\').textContent} (${rentalDays} ng\\u00e0y)`;\\r\\n    const pickupLoc = locInput.value.trim() || activeCar.areaLabel;\\r\\n\\r\\n    const oldText = submitBtn.textContent;\\r\\n    submitBtn.disabled = true;\\r\\n    submitBtn.textContent = \'\\u0110ang g\\u1eedi th\\u00f4ng tin...\';\\r\\n\\r\\n    try {\\r\\n      const formData = new FormData();\\r\\n      formData.append(\'action\', \'crpc_save_quick_booking\');\\r\\n      formData.append(\'cust_name\', name);\\r\\n      formData.append(\'cust_phone\', phone);\\r\\n      formData.append(\'car_info\', `${activeCar.name} (${activeCar.plate})`);\\r\\n      formData.append(\'rent_mode\', selectedMode);\\r\\n      formData.append(\'location\', pickupLoc);\\r\\n      formData.append(\'rent_time\', rentTimeText);\\r\\n      formData.append(\'total_price\', total);\\r\\n\\r\\n      const ajaxUrl = window.crpcAjaxUrl || \'\\/wp-admin\\/admin-ajax.php\';\\r\\n      const res = await fetch(ajaxUrl, { method: \'POST\', body: formData });\\r\\n      const data = await res.json();\\r\\n\\r\\n      if (data.success) {\\r\\n        const targetCar = carsData.find(c => c.id === activeCar.id);\\r\\n        if (targetCar) {\\r\\n          targetCar.bookedRanges.push({ start: startInput.value, end: endInput.value });\\r\\n        }\\r\\n        this.reset();\\r\\n        modalEl.classList.remove(\'open\');\\r\\n        renderCars();\\r\\n        showToast(`\\u0110\\u00e3 g\\u1eedi y\\u00eau c\\u1ea7u thu\\u00ea ${activeCar.name}! Ch\\u00fang t\\u00f4i s\\u1ebd g\\u1ecdi s\\u1ed1 ${phone} \\u0111\\u1ec3 x\\u00e1c nh\\u1eadn.`);\\r\\n      } else {\\r\\n        showToast(data.data || \'C\\u00f3 l\\u1ed7i x\\u1ea3y ra, vui l\\u00f2ng th\\u1eed l\\u1ea1i.\', true);\\r\\n      }\\r\\n    } catch (err) {\\r\\n      showToast(\'Kh\\u00f4ng th\\u1ec3 k\\u1ebft n\\u1ed1i m\\u00e1y ch\\u1ee7 WordPress.\', true);\\r\\n    } finally {\\r\\n      submitBtn.disabled = false;\\r\\n      submitBtn.textContent = oldText;\\r\\n    }\\r\\n  });\\r\\n\\r\\n  modalEl.addEventListener(\'click\', (e) => {\\r\\n    if (e.target === modalEl) modalEl.classList.remove(\'open\');\\r\\n  });\\r\\n\\r\\n  document.getElementById(\'crpcBookingForm\').add