name}! Ch\\u00fang t\\u00f4i s\\u1ebd g\\u1ecdi s\\u1ed1 ${phone} \\u0111\\u1ec3 x\\u00e1c nh\\u1eadn.`);\\r\\n      } else {\\r\\n        showToast(data.data || \'C\\u00f3 l\\u1ed7i x\\u1ea3y ra, vui l\\u00f2ng th\\u1eed l\\u1ea1i.\', true);\\r\\n      }\\r\\n    } catch (err) {\\r\\n      showToast(\'Kh\\u00f4ng th\\u1ec3 k\\u1ebft n\\u1ed1i m\\u00e1y ch\\u1ee7 WordPress.\', true);\\r\\n    } finally {\\r\\n      submitBtn.disabled = false;\\r\\n      submitBtn.textContent = oldText;\\r\\n    }\\r\\n  });\\r\\n<\\/script>\"},\"elements\":[],\"widgetType\":\"html\"}],\"isInner\":true},{\"id\":\"c07f08f\",\"elType\":\"widget\",\"settings\":{\"editor\":\"<p>Check out xe n\\u1ed5i b\\u1eadt<\\/p>\",\"typography_typography\":\"custom\",\"typography_font_size\":{\"unit\":\"px\",\"size\":18,\"sizes\":[]},\"typography_font_weight\":\"500\",\"align_mobile\":\"center\",\"text_color\":\"#A5AAAE\",\"typography_font_size_tablet\":{\"unit\":\"px\",\"size\":18,\"sizes\":[]},\"__globals__\":{\"text_color\":\"\"},\"align_tablet\":\"center\",\"align\":\"center\"},\"elements\":[],\"widgetType\":\"text-editor\"},{\"id\":\"d3bee39\",\"elType\":\"widget\",\"settings\":{\"title\":\"Xe N\\u1ed5i B\\u1eadt\",\"typography_typography\":\"custom\",\"typography_font_size\":{\"unit\":\"px\",\"size\":40,\"sizes\":[]},\"align\":\"center\",\"typography_font_size_tablet\":{\"unit\":\"px\",\"size\":30,\"sizes\":[]}},\"elements\":[],\"widgetType\":\"heading\"}],\"isInner\":false},{\"id\":\"d27e7e9\",\"elType\":\"container\",\"settings\":{\"flex_direction\":\"row\",\"flex_align_items\":\"stretch\",\"flex_gap\":{\"size\":10,\"column\":\"10\",\"row\":\"10\",\"unit\":\"px\"},\"flex_justify_content\":\"center\",\"margin\":{\"unit\":\"px\",\"top\":\"0\",\"right\":\"0\",\"bottom\":\"130\",\"left\":\"0\",\"isLinked\":false},\"margin_tablet\":{\"unit\":\"px\",\"top\":\"0\",\"right\":\"0\",\"bottom\":\"80\",\"left\":\"0\",\"isLinked\":false},\"padding\":{\"unit\":\"px\",\"top\":\"0\",\"right\":\"0\",\"bottom\