n    padding: 28px;\\r\\n    background-color: #ffffff;\\r\\n    color: #111827;\\r\\n    border-radius: 16px;\\r\\n    border: 1px solid #e5e7eb;\\r\\n    box-shadow: 0 10px 30px rgba(0, 0, 0, 0.06);\\r\\n    position: relative;\\r\\n  }\\r\\n\\r\\n  \\/* 1. Thanh Tab ch\\u1ebf \\u0111\\u1ed9 thu\\u00ea *\\/\\r\\n  #wpCarRentalPC .crpc-top-row {\\r\\n    display: flex;\\r\\n    justify-content: space-between;\\r\\n    align-items: center;\\r\\n    flex-wrap: wrap;\\r\\n    gap: 12px;\\r\\n    margin-bottom: 18px;\\r\\n  }\\r\\n\\r\\n  #wpCarRentalPC .crpc-tabs {\\r\\n    position: relative;\\r\\n    display: inline-flex;\\r\\n    background-color: #f3f4f6;\\r\\n    padding: 5px;\\r\\n    border-radius: 12px;\\r\\n    border: 1px solid #e5e7eb;\\r\\n    gap: 6px;\\r\\n  }\\r\\n\\r\\n  #wpCarRentalPC .crpc-tab-btn {\\r\\n    position: relative;\\r\\n    z-index: 2;\\r\\n    display: flex;\\r\\n    align-items: center;\\r\\n    gap: 8px;\\r\\n    padding: 10px 22px;\\r\\n    border-radius: 9px;\\r\\n    border: none;\\r\\n    background: transparent;\\r\\n    color: #4b5563;\\r\\n    font-size: 15px;\\r\\n    font-weight: 600;\\r\\n    cursor: pointer;\\r\\n    transition: color 0.25s ease, background-color 0.25s ease, box-shadow 0.25s ease;\\r\\n  }\\r\\n\\r\\n  #wpCarRentalPC .crpc-tab-btn:hover {\\r\\n    color: #111827;\\r\\n  }\\r\\n\\r\\n  #wpCarRentalPC .crpc-tab-btn svg {\\r\\n    width: 18px;\\r\\n    height: 18px;\\r\\n    stroke: currentColor;\\r\\n    fill: none;\\r\\n    stroke-width: 2;\\r\\n    transition: transform 0.25s ease;\\r\\n  }\\r\\n\\r\\n  #wpCarRentalPC .crpc-tab-btn.active {\\r\\n    background-color: #ffffff;\\r\\n    color: #d9383a;\\r\\n    box-shadow: 0 2px 8px rgba(0, 0, 0, 0.08);\\r\\n  }\\r\\n\\r\\n  #wpCarRentalPC .crpc-tab-btn.active svg {\\r\\n    color: #d9383a;\\r\\n    transform: scale(1.08);\\r\\n  }\\r\\n\\r\\n  #wpCarRentalPC .crpc-live-status {\\r\\n    display: inline-flex;\\r\\n    align-items: center;\\r\\n    gap: 8px;\\r\\n    font-size: 13px;\\r\\n    color: #4b5563;\\r\\n    background: #f9fafb;\\r\\n    padding: 8px 14px;\\r\\n    border-radius: 999px;\\r\\n    border: 1px solid #e5e7eb;\\r\\n  }\\r\\n\\r\\n  #wpCarRentalPC .crpc-pulse-dot {\\r\\n    width: 8px;\\r\\n    height: 8px;\\r\\n    border-radius: 50%;\\r\\n    background-color: #10b981;\\r\\n    box-shadow: 0 0 0 0 rgba(16, 185, 129, 0.6);\\r\\n    animation: crpcPulse 2s infinite;\\r\\n  }\\r\\n\\r\\n  @keyframes crpcPulse {\\r\\n    0% { box-shadow: 0 0 0 0 rgba(16, 185, 129, 0.6); }\\r\\n    70% { box-shadow: 0 0 0 7px rgba(16, 185, 129, 0); }\\r\\n    100% { box-shadow: 0 0 0 0 rgba(16, 185, 129, 0); }\\r\\n  }\\r\\n\\r\\n  \\/* 2. Thanh t\\u00ecm ki\\u1ebfm ngang cho Laptop\\/PC *\\/\\r\\n  #wpCarRentalPC .crpc-search-bar {\\r\\n    position: relative;\\r\\n    display: grid;\\r\\n    grid-template-columns: 1.5fr 1.25fr 170px;\\r\\n    gap: 16px;\\r\\n    align-items: center;\\r\\n    background-color: #ffffff;\\r\\n    border: 1px solid #d1d5db;\\r\\n    border-radius: 14px;\\r\\n    padding: 14px 18px;\\r\\n    margin-bottom: 22px;\\r\\n    box-shadow: 0 4px 16px rgba(0, 0, 0, 0.04);\\r\\n    transition: border-color 0.25s ease, box-shadow 0.25s ease;\\r\\n  }\\r\\n\\r\\n  #wpCarRentalPC .crpc-search-bar:focus-within {\\r\\n    border-color: #d9383a;\\r\\n    box-shadow: 0 0 0 3px rgba(217, 56, 58, 0.14);\\r\\n  }\\r\\n\\r\\n  #wpCarRentalPC .crpc-field {\\r\\n    position: relative;\\r\\n    display: flex;\\r\\n    align-items: center;\\r\\n    gap: 14px;\\r\\n    padding: 6px 12px;\\r\\n    border-right: 1px solid #e5e7eb;\\r\\n    border-radius: 10px;\\r\\n    transition: background-color 0.2s ease;\\r\\n  }\\r\\n\\r\\n  #wpCarRentalPC .crpc-field:hover {\\r\\n    background-color: #f9fafb;\\r\\n  }\\r\\n\\r\\n  #wpCarRentalPC .crpc-field:last-of-type {\\r\\n    border-right: none;\\r\\n  }\\r\\n\\r\\n  #wpCarRentalPC .crpc-icon-box {\\r\\n    width: 42px;\\r\\n    height: 42px;\\r\\n    min-width: 42px;\\r\\n    border-radius: 10px;\\r\\n    background-color: #fef2f2;\\r\\n    display: flex;\\r\\n    align-items: center;\\r\\n    justify-content: center;\\r\\n    color: #d9383a;\\r\\n    transition: background-color 0.2s ease, color 0.2s ease;\\r\\n  }\\r\\n\\r\\n  #wpCarRentalPC .crpc-field:hover .crpc-icon-box {\\r\\n    background-color: #fee2e2;\\r\\n    color: #b91c1c;\\r\\n  }\\r\\n\\r\\n  #wpCarRentalPC .crpc-icon-box svg {\\r\\n    width: 20px;\\r\\n    height: 20px;\\r\\n    stroke: currentColor;\\r\\n    fill: none;\\r\\n    stroke-width: 2;\\r\\n  }\\r\\n\\r\\n  #wpCarRentalPC .crpc-field-content {\\r\\n    display: flex;\\r\\n    flex-direction: column;\\r\\n    width: 100%;\\r\\n    position: relative;\\r\\n    min-width: 0;\\r\\n  }\\r\\n\\r\\n  #wpCarRentalPC .crpc-label-row {\\r\\n    display: flex;\\r\\n    align-items: center;\\r\\n    justify-content: space-between;\\r\\n    gap: 8px;\\r\\n    margin-bottom: 4px;\\r\\n  }\\r\\n\\r\\n  #wpCarRentalPC .crpc-field-label {\\r\\n    font-size: 12px;\\r\\n    color: #6b7280;\\r\\n  }\\r\\n\\r\\n  \\/* N\\u00fat \\u0111\\u1ecbnh v\\u1ecb v\\u1ecb tr\\u00ed hi\\u1ec7n t\\u1ea1i *\\/\\r\\n  #wpCarRentalPC .crpc-gps-btn {\\r\\n    display: inline-flex;\\r\\n    align-items: center;\\r\\n    gap: 5px;\\r\\n    background-color: #fef2f2;\\r\\n    color: #d9383a;\\r\\n    border: 1px solid #fecaca;\\r\\n    border-radius: 999px;\\r\\n    padding: 3px 10px;\\r\\n    font-size: 11px;\\r\\n    font-weight: 700;\\r\\n    cursor: pointer;\\r\\n    transition: all 0.2s ease;\\r\\n    white-space: nowrap;\\r\\n  }\\r\\n\\r\\n  #wpCarRentalPC .crpc-gps-btn:hover {\\r\\n    background-color: #d9383a;\\r\\n    color: #ffffff;\\r\\n    border-color: #d9383a;\\r\\n  }\\r\\n\\r\\n  #wpCarRentalPC .crpc-gps-btn svg {\\r\\n    width: 12px;\\r\\n    height: 12px;\\r\\n    stroke: currentColor;\\r\\n    fill: none;\\r\\n    stroke-width: 2.2;\\r\\n  }\\r\\n\\r\\n  #wpCarRentalPC .crpc-gps-btn.is-locating svg {\\r\\n    animation: crpcSpin 0.8s linear infinite;\\r\\n  }\\r\\n\\r\\n  #wpCarRentalPC .crpc-input-wrap {\\r\\n    display: flex;\\r\\n    align-items: center;\\r\\n    gap: 6px;\\r\\n  }\\r\\n\\r\\n  #wpCarRentalPC .crpc-input {\\r\\n    width: 100%;\\r\\n    background: transparent;\\r\\n    border: none;\\r\\n    color: #111827;\\r\\n    font-size: 15px;\\r\\n    font-weight: 700;\\r\\n    padding: 0;\\r\\n    outline: none;\\r\\n    text-overflow: ellipsis;\\r\\n  }\\r\\n\\r\\n  #wpCarRentalPC .crpc-clear-loc {\\r\\n    background: #e5e7eb;\\r\\n    border: none;\\r\\n    color: #4b5563;\\r\\n    width: 20px;\\r\\n    height: 20px;\\r\\n    border-radius: 50%;\\r\\n    font-size: 11px;\\r\\n    cursor: pointer;\\r\\n    display: none;\\r\\n    align-items: center;\\r\\n    justify-content: center;\\r\\n    flex-shrink: 0;\\r\\n  }\\r\\n\\r\\n  #wpCarRentalPC .crpc-clear-loc:hover {\\r\\n    background: #d1d5db;\\r\\n    color: #111827;\\r\\n  }\\r\\n\\r\\n  \\/* Dropdown g\\u1ee3i \\u00fd \\u0111\\u1ecba \\u0111i\\u1ec3m *\\/\\r\\n  #wpCarRentalPC .crpc-loc-dropdown {\\r\\n    display: none;\\r\\n    position: absolute;\\r\\n    top: calc(100% + 14px);\\r\\n    left: -12px;\\r\\n    width: 390px;\\r\\n    max-width: 90vw;\\r\\n    background-color: #ffffff;\\r\\n    border: 1px solid #e5e7eb;\\r\\n    border-radius: 12px;\\r\\n    padding: 8px;\\r\\n    box-shadow: 0 16px 32px rgba(0, 0, 0, 0.14);\\r\\n    z-index: 50;\\r\\n    animation: crpcFadeDown 0.18s ease-out;\\r\\n  }\\r\\n\\r\\n  #wpCarRentalPC .crpc-loc-dropdown.open {\\r\\n    display: block;\\r\\n  }\\r\\n\\r\\n  #wpCarRentalPC .crpc-loc-gps-option {\\r\\n    display: flex;\\r\\n    align-items: center;\\r\\n    gap: 10px;\\r\\n    padding: 10px;\\r\\n    border-radius: 8px;\\r\\n    background-color: #fef2f2;\\r\\n    border: 1px solid #fecaca;\\r\\n    cursor: pointer;\\r\\n    margin-bottom: 6px;\\r\\n    transition: background-color 0.15s ease;\\r\\n  }\\r\\n\\r\\n  #wpCarRentalPC .crpc-loc-gps-option:hover {\\r\\n    background-color: #fee2e2;\\r\\n  }\\r\\n\\r\\n  #wpCarRentalPC .crpc-loc-gps-option .crpc-loc-item-title {\\r\\n    color: #d9383a;\\r\\n  }\\r\\n\\r\\n  #wpCarRentalPC .crpc-loc-header {\\r\\n    font-size: 11px;\\r\\n    font-weight: 700;\\r\\n    text-transform: uppercase;\\r\\n    color: #9ca3af;\\r\\n    padding: 6px 10px;\\r\\n    letter-spacing: 0.5px;\\r\\n  }\\r\\n\\r\\n  #wpCarRentalPC .crpc-loc-item {\\r\\n    display: flex;\\r\\n    align-items: center;\\r\\n    gap: 10px;\\r\\n    padding: 10px;\\r\\n    border-radius: 8px;\\r\\n    cursor: pointer;\\r\\n    transition: background-color 0.15s ease;\\r\\n  }\\r\\n\\r\\n  #wpCarRentalPC .crpc-loc-item:hover {\\r\\n    background-color: #f9fafb;\\r\\n  }\\r\\n\\r\\n  #wpCarRentalPC .crpc-loc-item-title {\\r\\n    font-size: 13px;\\r\\n    font-weight: 600;\\r\\n    color: #111827;\\r\\n  }\\r\\n\\r\\n  #wpCarRentalPC .crpc-loc-item-sub {\\r\\n    font-size: 11px;\\r\\n    color: #6b7280;\\r\\n  }\\r\\n\\r\\n  #wpCarRentalPC .crpc-time-display {\\r\\n    font-size: 15px;\\r\\n    font-weight: 700;\\r\\n    color: #111827;\\r\\n    cursor: pointer;\\r\\n    display: flex;\\r\\n    align-items: center;\\r\\n    justify-content: space-between;\\r\\n    user-select: none;\\r\\n  }\\r\\n\\r\\n  #wpCarRentalPC .crpc-time-display:hover {\\r\\n    color: #d9383a;\\r\\n  }\\r\\n\\r\\n  #wpCarRentalPC .crpc-search-btn {\\r\\n    height: 52px;\\r\\n    width: 100%;\\r\\n    background: linear-gradient(135deg, #d9383a 0%, #b91c1c 100%);\\r\\n    color: #ffffff;\\r\\n    border: none;\\r\\n    border-radius: 10px;\\r\\n    font-size: 16px;\\r\\n    font-weight: 700;\\r\\n    cursor: pointer;\\r\\n    display: flex;\\r\\n    align-items: center;\\r\\n    justify-content: center;\\r\\n    gap: 8px;\\r\\n    transition: transform 0.15s ease, box-shadow 0.2s ease, filter 0.2s ease;\\r\\n  }\\r\\n\\r\\n  #wpCarRentalPC .crpc-search-btn:hover {\\r\\n    filter: brightness(1.06);\\r\\n    box-shadow: 0 6px 18px rgba(21