(3297, 3616, '_elementor_data', '[{\"id\":\"65d368b\",\"elType\":\"container\",\"settings\":{\"blocksy_stretch_section\":\"stretched\",\"content_position\":\"middle\",\"background_background\":\"classic\",\"background_color\":\"#F1F1F0\",\"text_align\":\"center\",\"padding\":{\"unit\":\"px\",\"top\":\"190\",\"right\":\"0\",\"bottom\":\"350\",\"left\":\"0\",\"isLinked\":false},\"padding_tablet\":{\"unit\":\"px\",\"top\":\"120\",\"right\":\"0\",\"bottom\":\"340\",\"left\":\"0\",\"isLinked\":false},\"padding_mobile\":{\"unit\":\"px\",\"top\":\"110\",\"right\":\"0\",\"bottom\":\"310\",\"left\":\"0\",\"isLinked\":false},\"flex_direction\":\"column\",\"flex_align_items\":\"center\",\"flex_gap\":{\"size\":20,\"column\":\"20\",\"row\":\"20\",\"unit\":\"px\",\"isLinked\":true}},\"elements\":[{\"id\":\"499be08\",\"elType\":\"widget\",\"settings\":{\"html\":\"<style>\\r\\n  .car-booking-box {\\r\\n    max-width: 850px;\\r\\n    margin: 30px auto;\\r\\n    padding: 32px;\\r\\n    background: #ffffff;\\r\\n    border: 2px solid #111111;\\r\\n    border-radius: 8px;\\r\\n    box-shadow: 0 10px 25px rgba(0, 0, 0, 0.08);\\r\\n    font-family: inherit;\\r\\n    color: #111111;\\r\\n  }\\r\\n  .car-booking-title {\\r\\n    text-align: center;\\r\\n    font-size: 24px;\\r\\n    font-weight: 700;\\r\\n    text-transform: uppercase;\\r\\n    margin-bottom: 8px;\\r\\n    letter-spacing: 1px;\\r\\n  }\\r\\n  .car-booking-subtitle {\\r\\n    text-align: center;\\r\\n    font-size: 14px;\\r\\n    color: #666666;\\r\\n    margin-bottom: 24px;\\r\\n  }\\r\\n  .booking-grid {\\r\\n    display: grid;\\r\\n    grid-template-columns: repeat(2, 1fr);\\r\\n    gap: 18px;\\r\\n  }\\r\\n  .booking-group {\\r\\n    display: flex;\\r\\n    flex-direction: column;\\r\\n  }\\r\\n  .booking-group.full-width {\\r\\n    grid-column: span 2;\\r\\n  }\\r\\n  .booking-group label {\\r\\n    font-size: 13px;\\r\\n    font-weight: 700;\\r\\n    margin-bottom: 6px;\\r\\n    text-transform: uppercase;\\r\\n  }\\r\\n  .booking-group input,\\r\\n  .booking-group select {\\r\\n    padding: 12px 14px;\\r\\n    border: 1px solid #cccccc;\\r\\n    border-radius: 4px;\\r\\n    font-size: 15px;\\r\\n    background: #fafafa;\\r\\n    transition: border-color 0.2s;\\r\\n  }\\r\\n  .booking-group input:focus,\\r\\n  .booking-group select:focus {\\r\\n    outline: none;\\r\\n    border-color: #d9383a;\\r\\n    background: #ffffff;\\r\\n  }\\r\\n  .booking-submit-btn {\\r\\n    width: 100%;\\r\\n    margin-top: 22px;\\r\\n    padding: 15px;\\r\\n    background-color: #d9383a;\\r\\n    color: #ffffff;\\r\\n    border: none;\\r\\n    border-radius: 4px;\\r\\n    font-size: 16px;\\r\\n    font-weight: 700;\\r\\n    text-transform: uppercase;\\r\\n    cursor: pointer;\\r\\n    transition: background-color 0.25s;\\r\\n  }\\r\\n  .booking-submit-btn:hover {\\r\\n    background-color: #b5282a;\\r\\n  }\\r\\n  .booking-result {\\r\\n    margin-top: 16px;\\r\\n    padding: 14px;\\r\\n    border-radius: 4px;\\r\\n    background: #f4f4f4;\\r\\n    border-left: 4px solid #d9383a;\\r\\n    font-size: 14px;\\r\\n    display: none;\\r\\n  }\\r\\n  @media (max-width: 600px) {\\r\\n    .booking-grid {\\r\\n      grid-template-columns: 1fr;\\r\\n    }\\r\\n    .booking-group.full-width {\\r\\n      grid-column: span 1;\\r\\n    }\\r\\n  }\\r\\n<\\/style>\\r\\n\\r\\n<div class=\\\"car-booking-box\\\">\\r\\n  <div class=\\\"car-booking-title\\\">\\u0110\\u1eb7t L\\u1ecbch Thu\\u00ea Xe<\\/div>\\r\\n  <div class=\\\"car-booking-subtitle\\\">Ch\\u1ecdn d\\u00f2ng xe v\\u00e0 th\\u1eddi gian nh\\u1eadn \\u2013 tr\\u1ea3 xe mong mu\\u1ed1n<\\/div>\\r\\n\\r\\n  <form id=\\\"carRentalForm\\\">\\r\\n    <div class=\\\"booking-grid\\\">\\r\\n      <div class=\\\"booking-group full-width\\\">\\r\\n        <label for=\\\"carSelect\\\">Ch\\u1ecdn d\\u00f2ng xe<\\/label>\\r\\n        <select id=\\\"carSelect\\\" required>\\r\\n          <option value=\\\"8000000\\\" data-name=\\\"Bugatti Bolide\\\">Bugatti Bolide \\u2013 8.000.000 \\u20ab\\/ng\\u00e0y<\\/option>\\r\\n          <option value=\\\"4000000\\\" data-name=\\\"Nissan GT-R Nismo\\\">Nissan GT-R Nismo \\u2013 4.000.000 \\u20ab\\/ng\\u00e0y<\\/option>\\r\\n          <option value=\\\"1300000\\\" data-name=\\\"Ford Territory\\\">Ford Territory \\u2013 1.300.000 \\u20ab\\/ng\\u00e0y<\\/option>\\r\\n          <option value=\\\"480000\\\" data-name=\\\"VinFast VF3 Normal\\\">VinFast VF3 Normal \\u2013 480.000 \\u20ab\\/ng\\u00e0y<\\/option>\\r\\n        <\\/select>\\r\\n      <\\/div>\\r\\n\\r\\n      <div class=\\\"booking-group\\\">\\r\\n        <label for=\\\"pickupDate\\\">Ng\\u00e0y nh\\u1eadn xe<\\/label>\\r\\n        <input type=\\\"date\\\" id=\\\"pickupDate\\\" required>\\r\\n      <\\/div>\\r\\n\\r\\n      <div class=\\\"booking-group\\\">\\r\\n        <label for=\\\"returnDate\\\">Ng\\u00e0y tr\\u1ea3 xe<\\/label>\\r\\n        <input type=\\\"date\\\" id=\\\"returnDate\\\" required>\\r\\n      <\\/div>\\r\\n\\r\\n      <div class=\\\"booking-group\\\">\\r\\n        <label for=\\\"customerName\\\">H\\u1ecd v\\u00e0 t\\u00ean<\\/label>\\r\\n        <input type=\\\"text\\\" id=\\\"customerName\\\" placeholder=\\\"Nh\\u1eadp h\\u1ecd t\\u00ean c\\u1ee7a b\\u1ea1n\\\" required>\\r\\n      <\\/div>\\r\\n\\r\\n      <div class=\\\"booking-group\\\">\\r\\n        <label for=\\\"customerPhone\\\">S\\u1ed1 \\u0111i\\u1ec7n tho\\u1ea1i<\\/label>\\r\\n        <input type=\\\"tel\\\" id=\\\"customerPhone\\\" placeholder=\\\"Nh\\u1eadp s\\u1ed1 \\u0111i\\u1ec7n tho\\u1ea1i li\\u00ean h\\u1ec7\\\" required>\\r\\n      <\\/div>\\r\\n    <\\/div>\\r\\n\\r\\n    <button type=\\\"submit\\\" class=\\\"booking-submit-btn\\\">X\\u00e1c Nh\\u1eadn \\u0110\\u1eb7t L\\u1ecbch<\\/button>\\r\\n    <div class=\\\"booking-result\\\" id=\\\"bookingResult\\\"><\\/div>\\r\\n  <\\/form>\\r\\n<\\/div>\\r\\n\\r\\n<script>\\r\\n  document.getElementById(\'carRentalForm\').addEventListener(\'submit\', function(e) {\\r\\n    e.preventDefault();\\r\\n    const carSelect = document.getElementById(\'carSelect\');\\r\\n    const carName = carSelect.options[carSelect.selectedIndex].getAttribute(\'data-name\');\\r\\n    const pricePerDay = parseInt(carSelect.value);\\r\\n    const pickup = new Date(document.getElementById(\'pickupDate\').value);\\r\\n    const dropoff = new Date(document.getElementById(\'returnDate\').value);\\r\\n    const name = document.getElementById(\'customerName\').value;\\r\\n    const phone = document.getElementById(\'customerPhone\').value;\\r\\n    const resultBox = document.getElementById(\'bookingResult\');\\r\\n\\r\\n    const diffDays = Math.ceil((dropoff - pickup) \\/ (1000 * 60 * 60 * 24));\\r\\n    resultBox.style.display = \'block\';\\r\\n\\r\\n    if (diffDays <= 0) {\\r\\n      resultBox.innerHTML = \'\\u26a0\\ufe0f <strong>L\\u1ed7i:<\\/strong> Ng\\u00e0y tr\\u1ea3 xe ph\\u1ea3i sau ng\\u00e0y nh\\u1eadn xe \\u00edt nh\\u1ea5t 1 ng\\u00e0y.\';\\r\\n      return;\\r\\n    }\\r\\n\\r\\n    const total = (diffDays * pricePerDay).toLocaleString(\'vi-VN\');\\r\\n    resultBox.innerHTML = `\\u2705 C\\u1ea3m \\u01a1n <strong>${name}<\\/strong>! Y\\u00eau c\\u1ea7u thu\\u00ea xe <strong>${carName}<\\/strong> (${diffDays} ng\\u00e0y \\u2013 T\\u1ea1m t\\u00ednh: <strong>${total} \\u20ab<\\/strong>) \\u0111\\u00e3 \\u0111\\u01b0\\u1ee3c ghi nh\\u1eadn. Ch\\u00fang t\\u00f4i s\\u1ebd g\\u1ecdi l\\u1ea1i s\\u1ed1 <strong>${phone}<\\/strong> \\u0111\\u1ec3 x\\u00e1c nh\\u1eadn.`;\\r\\n  });\\r\\n<\\/script>\"},\"elements\":[],\"widgetType\":\"html\"},{\"id\":\"c3ab758\",\"elType\":\"widget\",\"settings\":{\"shortcode\":\"[blocksy_breadcrumbs]\",\"_margin_mobile\":{\"unit\":\"px\",\"top\":\"10\",\"right\":\"0\",\"bottom\":\"0\",\"left\":\"0\",\"isLinked\":false}},\"elements\":[],\"widgetType\":\"shortcode\"},{\"id\":\"8117abb\",\"elType\":\"container\",\"settings\":{\"content_width\":\"full\"},\"elements\":[],\"isInner\":true},{\"id\":\"f840f91\",\"elType\":\"widget\",\"settings\":{\"title\":\"D