(3308, 3617, '_elementor_data', '[{\"id\":\"65d368b\",\"elType\":\"container\",\"settings\":{\"blocksy_stretch_section\":\"stretched\",\"content_position\":\"middle\",\"background_background\":\"classic\",\"background_color\":\"#F1F1F0\",\"text_align\":\"center\",\"padding\":{\"unit\":\"px\",\"top\":\"190\",\"right\":\"0\",\"bottom\":\"350\",\"left\":\"0\",\"isLinked\":false},\"padding_tablet\":{\"unit\":\"px\",\"top\":\"120\",\"right\":\"0\",\"bottom\":\"340\",\"left\":\"0\",\"isLinked\":false},\"padding_mobile\":{\"unit\":\"px\",\"top\":\"110\",\"right\":\"0\",\"bottom\":\"310\",\"left\":\"0\",\"isLinked\":false},\"flex_direction\":\"column\",\"flex_align_items\":\"center\",\"flex_gap\":{\"size\":20,\"column\":\"20\",\"row\":\"20\",\"unit\":\"px\",\"isLinked\":true}},\"elements\":[{\"id\":\"499be08\",\"elType\":\"widget\",\"settings\":{\"html\":\"<style>\\r\\n  .crpc-srv-card {\\r\\n    max-width: 470px;\\r\\n    margin: 32px auto;\\r\\n    padding: 32px 28px;\\r\\n    background: #ffffff;\\r\\n    border: 1.5px solid #1f2937;\\r\\n    border-radius: 14px;\\r\\n    box-shadow: 0 12px 30px rgba(0, 0, 0, 0.08);\\r\\n    font-family: -apple-system, BlinkMacSystemFont, \\\"Segoe UI\\\", Roboto, sans-serif;\\r\\n  }\\r\\n  .crpc-srv-card * {\\r\\n    box-sizing: border-box;\\r\\n  }\\r\\n  .crpc-srv-title {\\r\\n    margin: 0 0 6px 0;\\r\\n    text-align: center;\\r\\n    font-size: 20px;\\r\\n    font-weight: 800;\\r\\n    color: #111827;\\r\\n    text-transform: uppercase;\\r\\n    letter-spacing: 0.5px;\\r\\n  }\\r\\n  .crpc-srv-sub {\\r\\n    margin: 0 0 22px 0;\\r\\n    text-align: center;\\r\\n    font-size: 12.5px;\\r\\n    color: #6b7280;\\r\\n  }\\r\\n  .crpc-srv-group {\\r\\n    margin-bottom: 14px;\\r\\n  }\\r\\n  .crpc-srv-row {\\r\\n    display: grid;\\r\\n    grid-template-columns: 1fr 1fr;\\r\\n    gap: 12px;\\r\\n    margin-bottom: 14px;\\r\\n  }\\r\\n  .crpc-srv-label {\\r\\n    display: block;\\r\\n    margin-bottom: 6px;\\r\\n    font-size: 11px;\\r\\n    font-weight: 700;\\r\\n    color: #111827;\\r\\n    text-transform: uppercase;\\r\\n  }\\r\\n  .crpc-srv-control {\\r\\n    width: 100%;\\r\\n    height: 42px;\\r\\n    padding: 0 12px;\\r\\n    border: 1px solid #d1d5db;\\r\\n    border-radius: 8px;\\r\\n    background: #ffffff;\\r\\n    color: #111827;\\r\\n    font-size: 13px;\\r\\n    outline: none;\\r\\n    transition: border-color 0.2s, box-shadow 0.2s;\\r\\n  }\\r\\n  .crpc-srv-control:focus {\\r\\n    border-color: #d9383a;\\r\\n    box-shadow: 0 0 0 3px rgba(217, 56, 58, 0.12);\\r\\n  }\\r\\n  .crpc-srv-submit {\\r\\n    width: 100%;\\r\\n    height: 46px;\\r\\n    margin-top: 6px;\\r\\n    background: #d9383a;\\r\\n    color: #ffffff;\\r\\n    border: none;\\r\\n    border-radius: 8px;\\r\\n    font-size: 13px;\\r\\n    font-weight: 700;\\r\\n    text-transform: uppercase;\\r\\n    letter-spacing: 0.5px;\\r\\n    cursor: pointer;\\r\\n    transition: background-color 0.2s;\\r\\n  }\\r\\n  .crpc-srv-submit:hover:not(:disabled) {\\r\\n    background: #b91c1c;\\r\\n  }\\r\\n  .crpc-srv-submit:disabled {\\r\\n    opacity: 0.7;\\r\\n    cursor: not-allowed;\\r\\n  }\\r\\n  @media (max-width: 480px) {\\r\\n    .crpc-srv-row {\\r\\n      grid-template-columns: 1fr;\\r\\n    }\\r\\n  }\\r\\n<\\/style>\\r\\n\\r\\n<div class=\\\"crpc-srv-card\\\">\\r\\n  <h3 class=\\\"crpc-srv-title\\\">\\u0110\\u1eb6T L\\u1ecaCH THU\\u00ca XE<\\/h3>\\r\\n  <p class=\\\"crpc-srv-sub\\\">Ch\\u1ecdn d\\u00f2ng xe v\\u00e0 th\\u1eddi gian nh\\u1eadn \\u2013 tr\\u1ea3 xe mong mu\\u1ed1n<\\/p>\\r\\n\\r\\n  <form id=\\\"crpcServiceBookingForm\\\">\\r\\n    <div class=\\\"crpc-srv-group\\\">\\r\\n      <label class=\\\"crpc-srv-label\\\" for=\\\"srvCarSelect\\\">CH\\u1eccN D\\u00d2NG XE<\\/label>\\r\\n      <!-- Thay s\\u1ed1 \\u1edf value=\\\"...\\\" b\\u1eb1ng \\u0111\\u00fang ID s\\u1ea3n ph\\u1ea9m WooCommerce c\\u1ee7a t\\u1eebng xe -->\\r\\n      <select id=\\\"srvCarSelect\\\" class=\\\"crpc-srv-control\\\" required>\\r\\n        <option value=\\\"\\\">-- Ch\\u1ecdn d\\u00f2ng xe mu\\u1ed1n thu\\u00ea --<\\/option>\\r\\n        <option value=\\\"714\\\">Bugatti Bolide \\u2013 8.000.000 \\u0111\\/ng\\u00e0y<\\/option>\\r\\n        <option value=\\\"715\\\">VinFast VF8 \\u2013 1.200.000 \\u0111\\/ng\\u00e0y<\\/option>\\r\\n        <option value=\\\"716\\\">VinFast VF5 \\u2013 700.000 \\u0111\\/ng\\u00e0y<\\/option>\\r\\n        <option value=\\\"717\\\">VinFast VF3 \\u2013 480.000 \\u0111\\/ng\\u00e0y<\\/option>\\r\\n        <option value=\\\"720\\\">Ford Territory \\u2013 1.300.000 \\u0111\\/ng\\u00e0y<\\/option>\\r\\n      <\\/select>\\r\\n    <\\/div>\\r\\n\\r\\n    <div class=\\\"crpc-srv-row\\\">\\r\\n      <div>\\r\\n        <label class=\\\"crpc-srv-label\\\" for=\\\"srvPickupDate\\\">NG\\u00c0Y NH\\u1eacN XE<\\/label>\\r\\n        <input type=\\\"date\\\" id=\\\"srvPickupDate\\\" class=\\\"crpc-srv-control\\\" required>\\r\\n      <\\/div>\\r\\n      <div>\\r\\n        <label class=\\\"crpc-srv-label\\\" for=\\\"srvReturnDate\\\">NG\\u00c0Y TR\\u1ea2 XE<\\/label>\\r\\n        <input type=\\\"date\\\" id=\\\"srvReturnDate\\\" class=\\\"crpc-srv-control\\\" required>\\r\\n      <\\/div>\\r\\n    <\\/div>\\r\\n\\r\\n    <div class=\\\"crpc-srv-row\\\">\\r\\n      <div>\\r\\n        <label class=\\\"crpc-srv-label\\\" for=\\\"srvCustName\\\">H\\u1ecc V\\u00c0 T\\u00caN<\\/label>\\r\\n        <input type=\\\"text\\\" id=\\\"srvCustName\\\" class=\\\"crpc-srv-control\\\" placeholder=\\\"Nh\\u1eadp h\\u1ecd t\\u00ean c\\u1ee7a b\\u1ea1n\\\" required>\\r\\n      <\\/div>\\r\\n      <div>\\r\\n        <label class=\\\"crpc-srv-label\\\" for=\\\"srvCustPhone\\\">S\\u1ed0 \\u0110I\\u1ec6N THO\\u1ea0I<\\/label>\\r\\n        <input type=\\\"tel\\\" id=\\\"srvCustPhone\\\" class=\\\"crpc-srv-control\\\" placeholder=\\\"Nh\\u1eadp s\\u1ed1 \\u0111i\\u1ec7n tho\\u1ea1i li\\u00ean h\\u1ec7\\\" required>\\r\\n      <\\/div>\\r\\n    <\\/div>\\r\\n\\r\\n    <button type=\\\"submit\\\" id=\\\"srvSubmitBtn\\\" class=\\\"crpc-srv-submit\\\">X\\u00c1C NH\\u1eacN \\u0110\\u1eb6T L\\u1ecaCH<\\/button>\\r\\n  <\\/form>\\r\\n<\\/div>\\r\\n\\r\\n<script>\\r\\n(function() {\\r\\n  const form = document.getElementById(\'crpcServiceBookingForm\');\\r\\n  if (!form) return;\\r\\n\\r\\n  form.addEventListener(\'submit\', async function(e) {\\r\\n    e.preventDefault();\\r\\n\\r\\n    const productId  = document.getElementById(\'srvCarSelect\').value;\\r\\n    const pickupDate = document.getElementById(\'srvPickupDate\').value;\\r\\n    const returnDate = document.getElementById(\'srvReturnDate\').value;\\r\\n    const custName   = document.getElementById(\'srvCustName\').value.trim();\\r\\n    const custPhone  = document.getElementById(\'srvCustPhone\').value.trim();\\r\\n    const submitBtn  = document.getElementById(\'srvSubmitBtn\');\\r\\n\\r\\n    if (!productId) {\\r\\n      alert(\'Vui l\\u00f2ng ch\\u1ecdn d\\u00f2ng xe mu\\u1ed1n thu\\u00ea!\');\\r\\n      return;\\r\\n    }\\r\\n\\r\\n    const start = new Date(pickupDate);\\r\\n    const end   = new Date(returnDate);\\r\\n    if (end < start) {\\r\\n      alert(\'Ng\\u00e0y tr\\u1ea3 xe ph\\u1ea3i c\\u00f9ng ng\\u00e0y ho\\u1eb7c sau ng\\u00e0y nh\\u1eadn xe!\');\\r\\n      return;\\r\\n    }\\r\\n\\r\\n    const days = Math.max(1, Math.ceil((end - start) \\/ (1000 * 60 * 60 * 24)));\\r\\n    const oldText = submitBtn.textContent;\\r\\n    submitBtn.disabled = true;\\r\\n    submitBtn.textContent = \'\\u0110ANG CHUY\\u1ec2N SANG GI\\u1ece H\\u00c0NG...\';\\r\\n\\r\\n    try {\\r\\n      const formData = new FormData();\\r\\n      formData.append(\'action\', \'crpc_service_booking_to_cart\');\\r\\n      formData.append(\'product_id\', productId);\\r\\n      formData.append(\'pickup_date\', pickupDate);\\r\\n      formData.append(\'return_date\', returnDate);\\r\\n      formData.append(\'cust_name\', custName);\\r\\n      formData.append(\'cust_phone\', custPhone);\\r\\n\\r\\n      const ajaxUrl = window.crpcAjaxUrl || \'\\/wp-admin\\/admin-ajax.php\';\\r\\n      const response = await fetch(ajaxUrl, {\\r\\n        method: \'POST\',\\r\\n        body: formData\\r\\n      });\\r\\n      const result = await response.json();\\r\\n\\r\\n      if (result.success && result.data.cart_url) {\\r\\n        window.location.href = result.data.cart_url;\\r\\n      } else {\\r\\n        const fallbackCart = window.crpcCartUrl || \'\\/cart\\/\';\\r\\n        const sep = fallbackCart.includes(\'?\') ? \'&\' : \'?\';\\r\\n        window.location.href = `${fallbackCart}${sep}add-to-cart=${productId}&quantity=${days}`;\\r\\n      }\\r\\n    } catch (err) {\\r\\n      const fallbackCart = window.crpcCartUrl || \'\\/cart\\/\';\\r\\n      const sep = fallbackCart.includes(\'?\') ? \'&\' : \'?\';\\r\\n      window.location.href = `${fallbackCart}${sep}add-to-cart=${productId}&quantity=${days}`;\\r\\n    } finally {\\r\\n      submitBtn.disabled = false;\\r\\n      submitBtn.textContent = oldText;\\r\\n    }\\r\\n  });\\r\\n})();\\r\\n<\\/script>\"},\"elements\":[],\"widgetType\":\"html\"},{\"id\":\"c3ab758\",\"elType\":\"widget\",\"settings\":{\"shortcode\":\"[blocksy_breadcrumbs]\",\"_margin_mobile\":{\"unit\":\"px\",\"top\":\"10\",\"right\":\"0\",\"bottom\":\"0\",\"left\":\"0\",\"isLinked\":false}},\"elements\":[],\"widgetType\":\"shortcode\"},{\"id\":\"8117abb\",\"elType\":\"container\",\"settings\":{\"content_width\":\"full\"},\"elements\":[],\"isInner\":true},{\"id\":\"f840f91\",\"elType\":\"widget\",\"settings\":{\"title\":\"D\\u1ecbch V\\u1ee5 C\\u1ee7a Ch\\u00fang T\\u00f4i\",\"align\":\"center\",\"typography_typography\":\"custom\",\"typography_font_size\":{\"unit\":\"px\",\"size\":70,\"sizes\":[]},\"_margin\":{\"unit\":\"px\",\"top\":\"15\",\"right\":\"0\",\"bottom\":\"0\",\"left\":\"0\",\"isLinked\":false},\"typography_font_size_tablet\":{\"unit\":\"px\",\"size\":40,\"sizes\":[]},\"_margin_mobile\":{\"unit\":\"px\",\"top\":\"5\",\"right\":\"0\",\"bottom\":\"0\",\"left\":\"0\",\"isLinked\"