INSERT INTO `wp_postmeta` (`meta_id`, `post_id`, `meta_key`, `meta_value`) VALUES
(3391, 3625, '_elementor_data', '[{\"id\":\"13967e8\",\"elType\":\"container\",\"settings\":[],\"elements\":[{\"id\":\"75b6831\",\"elType\":\"widget\",\"settings\":{\"html\":\"<style>\\r\\n  #crpcContactPage,\\r\\n  #crpcContactPage * {\\r\\n    box-sizing: border-box;\\r\\n    font-family: -apple-system, BlinkMacSystemFont, \\\"Segoe UI\\\", Roboto, Helvetica, Arial, sans-serif;\\r\\n  }\\r\\n\\r\\n  #crpcContactPage {\\r\\n    width: 100%;\\r\\n    max-width: 1200px;\\r\\n    margin: 24px auto 48px auto;\\r\\n    padding: 0 16px;\\r\\n    color: #111827;\\r\\n  }\\r\\n\\r\\n  \\/* 1. Banner \\u0111\\u1ea7u trang *\\/\\r\\n  #crpcContactPage .crpc-ct-hero {\\r\\n    text-align: center;\\r\\n    padding: 36px 20px;\\r\\n    background: #f9fafb;\\r\\n    border: 1px solid #e5e7eb;\\r\\n    border-radius: 16px;\\r\\n    margin-bottom: 28px;\\r\\n  }\\r\\n\\r\\n  #crpcContactPage .crpc-ct-badge {\\r\\n    display: inline-block;\\r\\n    padding: 5px 14px;\\r\\n    background: #fef2f2;\\r\\n    color: #d9383a;\\r\\n    border: 1px solid #fecaca;\\r\\n    border-radius: 999px;\\r\\n    font-size: 12px;\\r\\n    font-weight: 700;\\r\\n    margin-bottom: 10px;\\r\\n  }\\r\\n\\r\\n  #crpcContactPage .crpc-ct-hero h1 {\\r\\n    margin: 0 0 10px 0;\\r\\n    font-size: 28px;\\r\\n    font-weight: 800;\\r\\n    color: #111827;\\r\\n  }\\r\\n\\r\\n  #crpcContactPage .crpc-ct-hero p {\\r\\n    margin: 0 auto;\\r\\n    max-width: 620px;\\r\\n    font-size: 14.5px;\\r\\n    color: #4b5563;\\r\\n    line-height: 1.6;\\r\\n  }\\r\\n\\r\\n  \\/* 2. 4 Th\\u1ebb li\\u00ean h\\u1ec7 nhanh *\\/\\r\\n  #crpcContactPage .crpc-ct-cards {\\r\\n    display: grid;\\r\\n    grid-template-columns: repeat(4, 1fr);\\r\\n    gap: 16px;\\r\\n    margin-bottom: 32px;\\r\\n  }\\r\\n\\r\\n  #crpcContactPage .crpc-ct-card {\\r\\n    background: #ffffff;\\r\\n    border: 1px solid #e5e7eb;\\r\\n    border-radius: 14px;\\r\\n    padding: 20px;\\r\\n    box-shadow: 0 4px 14px rgba(0, 0, 0, 0.03);\\r\\n    transition: transform 0.2s, border-color 0.2s;\\r\\n  }\\r\\n\\r\\n  #crpcContactPage .crpc-ct-card:hover {\\r\\n    transform: translateY(-3px);\\r\\n    border-color: #d9383a;\\r\\n  }\\r\\n\\r\\n  #crpcContactPage .crpc-ct-icon {\\r\\n    width: 42px;\\r\\n    height: 42px;\\r\\n    border-radius: 10px;\\r\\n    background: #fef2f2;\\r\\n    color: #d9383a;\\r\\n    display: flex;\\r\\n    align-items: center;\\r\\n    justify-content: center;\\r\\n    font-size: 20px;\\r\\n    margin-bottom: 12px;\\r\\n  }\\r\\n\\r\\n  #crpcContactPage .crpc-ct-card h3 {\\r\\n    margin: 0 0 6px 0;\\r\\n    font-size: 15px;\\r\\n    font-weight: 700;\\r\\n    color: #111827;\\r\\n  }\\r\\n\\r\\n  #crpcContactPage .crpc-ct-card p {\\r\\n    margin: 0 0 10px 0;\\r\\n    font-size: 13px;\\r\\n    color: #6b7280;\\r\\n    line-height: 1.5;\\r\\n  }\\r\\n\\r\\n  #crpcContactPage .crpc-ct-link {\\r\\n    display: inline-block;\\r\\n    font-size: 14px;\\r\\n    font-weight: 700;\\r\\n    color: #d9383a;\\r\\n    text-decoration: none;\\r\\n  }\\r\\n\\r\\n  #crpcContactPage .crpc-ct-link:hover {\\r\\n    text-decoration: underline;\\r\\n  }\\r\\n\\r\\n  \\/* 3. Kh\\u1ed1i ch\\u00ednh: Form g\\u1eedi y\\u00eau c\\u1ea7u + B\\u1ea3n \\u0111\\u1ed3 \\u0111i\\u1ec3m giao nh\\u1eadn *\\/\\r\\n  #crpcContactPage .crpc-ct-main {\\r\\n    display: grid;\\r\\n    grid-template-columns: 1.15fr 1fr;\\r\\n    gap: 24px;\\r\\n    margin-bottom: 36px;\\r\\n  }\\r\\n\\r\\n  #crpcContactPage .crpc-ct-box {\\r\\n    background: #ffffff;\\r\\n    border: 1px solid #e5e7eb;\\r\\n    border-radius: 16px;\\r\\n    padding: 26px;\\r\\n    box-shadow: 0 6px 20px rgba(0, 0, 0, 0.04);\\r\\n  }\\r\\n\\r\\n  #crpcContactPage .crpc-ct-box h2 {\\r\\n    margin: 0 0 6px 0;\\r\\n    font-size: 20px;\\r\\n    font-weight: 700;\\r\\n    color: #111827;\\r\\n  }\\r\\n\\r\\n  #crpcContactPage .crpc-ct-box-sub {\\r\\n    margin: 0 0 20px 0;\\r\\n    font-size: 13px;\\r\\n    color: #6b7280;\\r\\n  }\\r\\n\\r\\n  #crpcContactPage .crpc-ct-row {\\r\\n    display: grid;\\r\\n    grid-template-columns: 1fr 1fr;\\r\\n    gap: 14px;\\r\\n    margin-bottom: 14px;\\r\\n  }\\r\\n\\r\\n  #crpcContactPage .crpc-ct-group {\\r\\n    margin-bottom: 14px;\\r\\n  }\\r\\n\\r\\n  #crpcContactPage .crpc-ct-group label {\\r\\n    display: block;\\r\\n    font-size: 12.5px;\\r\\n    font-weight: 600;\\r\\n    color: #374151;\\r\\n    margin-bottom: 6px;\\r\\n  }\\r\\n\\r\\n  #crpcContactPage .crpc-ct-input,\\r\\n  #crpcContactPage .crpc-ct-textarea {\\r\\n    width: 100%;\\r\\n    padding: 11px 13px;\\r\\n    border: 1px solid #d1d5db;\\r\\n    border-radius: 8px;\\r\\n    font-size: 14px;\\r\\n    color: #111827;\\r\\n    background: #ffffff;\\r\\n    outline: none;\\r\\n    transition: border-color 0.2s, box-shadow 0.2s;\\r\\n  }\\r\\n\\r\\n  #crpcContactPage .crpc-ct-input:focus,\\r\\n  #crpcContactPage .crpc-ct-textarea:focus {\\r\\n    border-color: #d9383a;\\r\\n    box-shadow: 0 0 0 3px rgba(217, 56, 58, 0.12);\\r\\n  }\\r\\n\\r\\n  #crpcContactPage .crpc-ct-submit {\\r\\n    width: 100%;\\r\\n    padding: 13px 20px;\\r\\n    background: #d9383a;\\r\\n    color: #ffffff;\\r\\n    border: none;\\r\\n    border-radius: 8px;\\r\\n    font-size: 15px;\\r\\n    font-weight: 700;\\r\\n    cursor: pointer;\\r\\n    transition: background-color 0.2s;\\r\\n  }\\r\\n\\r\\n  #crpcContactPage .crpc-ct-submit:hover {\\r\\n    background: #b91c1c;\\r\\n  }\\r\\n\\r\\n  \\/* Tab ch\\u1ecdn chi nh\\u00e1nh b\\u1ea3n \\u0111\\u1ed3 *\\/\\r\\n  #crpcContactPage .crpc-hub-tabs {\\r\\n    display: flex;\\r\\n    gap: 8px;\\r\\n    margin-bottom: 14px;\\r\\n    flex-wrap: wrap;\\r\\n  }\\r\\n\\r\\n  #crpcContactPage .crpc-hub-btn {\\r\\n    padding: 7px 14px;\\r\\n    border-radius: 8px;\\r\\n    border: 1px solid #d1d5db;\\r\\n    background: #f9fafb;\\r\\n    color: #374151;\\r\\n    font-size: 13px;\\r\\n    font-weight: 600;\\r\\n    cursor: pointer;\\r\\n    transition: all 0.2s;\\r\\n  }\\r\\n\\r\\n  #crpcContactPage .crpc-hub-btn.active {\\r\\n    background: #d9383a;\\r\\n    border-color: #d9383a;\\r\\n    color: #ffffff;\\r\\n  }\\r\\n\\r\\n  #crpcContactPage .crpc-hub-info {\\r\\n    background: #f9fafb;\\r\\n    border: 1px solid #e5e7eb;\\r\\n    border-radius: 10px;\\r\\n    padding: 12px 14px;\\r\\n    font-size: 13px;\\r\\n    color: #374151;\\r\\n    line-height: 1.6;\\r\\n    margin-bottom: 14px;\\r\\n  }\\r\\n\\r\\n  #crpcContactPage .crpc-map-frame {\\r\\n    width: 100%;\\r\\n    height: 250px;\\r\\n    border: 1px solid #e5e7eb;\\r\\n    border-radius: 10px;\\r\\n  }\\r\\n\\r\\n  \\/* 4. C\\u00e2u h\\u1ecfi th\\u01b0\\u1eddng g\\u1eb7p (FAQ) thay th\\u1ebf ph\\u1ea7n New Arrivals *\\/\\r\\n  #crpcContactPage .crpc-faq-wrap {\\r\\n    background: #ffffff;\\r\\n    border: 1px solid #e5e7eb;\\r\\n    border-radius: 16px;\\r\\n    padding: 26px;\\r\\n  }\\r\\n\\r\\n  #crpcContactPage .crpc-faq-wrap h2 {\\r\\n    margin: 0 0 16px 0;\\r\\n    font-size: 20px;\\r\\n    font-weight: 700;\\r\\n    color: #111827;\\r\\n  }\\r\\n\\r\\n  #crpcContactPage .crpc-faq-item {\\r\\n    border-bottom: 1px solid #f3f4f6;\\r\\n    padding: 14px 0;\\r\\n  }\\r\\n\\r\\n  #crpcContactPage .crpc-faq-item:last-child {\\r\\n    border-bottom: none;\\r\\n    padding-bottom: 0;\\r\\n  }\\r\\n\\r\\n  #crpcContactPage .crpc-faq-q {\\r\\n    font-size: 15px;\\r\\n    font-weight: 700;\\r\\n    color: #111827;\\r\\n    cursor: pointer;\\r\\n    display: flex;\\r\\n    justify-content: space-between;\\r\\n    align-items: center;\\r\\n    gap: 12px;\\r\\n  }\\r\\n\\r\\n  #crpcContactPage .crpc-faq-a {\\r\\n    margin-top: 8px;\\r\\n    font-size: 13.5px;\\r\\n    color: #4b5563;\\r\\n    line-height: 1.6;\\r\\n    display: none;\\r\\n  }\\r\\n\\r\\n  #crpcContactPage .crpc-faq-item.open .crpc-faq-a {\\r\\n    display: block;\\r\\n  }\\r\\n\\r\\n  @media (max-width: 960px) {\\r\\n    #crpcContactPage .crpc-ct-cards {\\r\\n      grid-template-columns: repeat(2, 1fr);\\r\\n    }\\r\\n    #crpcContactPage .crpc-ct-main {\\r\\n      grid-template-columns: 1fr;\\r\\n    }\\r\\n  }\\r\\n\\r\\n  @media (max-width: 560px) {\\r\\n    #crpcContactPage .crpc-ct-cards,\\r\\n    #crpcContactPage .crpc-ct-row {\\r\\n      grid-template-columns: 1fr;\\r\\n    }\\r\\n  }\\r\\n<\\/style>\\r\\n\\r\\n<div id=\\\"crpcContactPage\\\">\\r\\n  <!-- \\u0110\\u1ea7u trang -->\\r\\n  <div class=\\\"crpc-ct-hero\\\">\\r\\n    <span class=\\\"crpc-ct-badge\\\">H\\u1ed6 TR\\u1ee2 \\u0110\\u1eb6T XE & C\\u1ee8U H\\u1ed8 24\\/7<\\/span>\\r\\n    <h1>Li\\u00ean h\\u1ec7 Car Rental Platform<\\/h1>\\r\\n    <p>C\\u1ea7n t\\u01b0 v\\u1ea5n ch\\u1ecdn xe t\\u1ef1 l\\u00e1i, b\\u00e1o gi\\u00e1 thu\\u00ea xe th\\u00e1ng cho doanh nghi\\u1ec7p ho\\u1eb7c \\u0111\\u0103ng k\\u00fd k\\u00fd g\\u1eedi xe nh\\u00e0n r\\u1ed7i? \\u0110\\u1ed9i ng\\u0169 \\u0111i\\u1ec1u ph\\u1ed1i lu\\u00f4n s\\u1eb5n s\\u00e0ng h\\u1ed7 tr\\u1ee3 b\\u1ea1n trong 5 ph\\u00fat.<\\/p>\\r\\n  <\\/div>\\r\\n\\r\\n  <!-- 4 K\\u00eanh li\\u00ean h\\u1ec7 nhanh -->\\r\\n  <div class=\\\"crpc-ct-cards\\\">\\r\\n    <div class=\\\"crpc-ct-card\\\">\\r\\n      <div class=\\\"crpc-ct-icon\\\">\\ud83d\\udcde<\\/div>\\r\\n      <h3>Hotline \\u0111\\u1eb7t xe 24\\/7<\\/h3>\\r\\n      <p>H\\u1ed7 tr\\u1ee3 ki\\u1ec3m tra xe tr\\u1ed1ng, giao xe g\\u1ea5p v\\u00e0 x\\u1eed l\\u00fd s\\u1ef1 c\\u1ed1 tr\\u00ean \\u0111\\u01b0\\u1eddng.<\\/p>\\r\\n      <a href=\\\"tel:0901234567\\\" class=\\\"crpc-ct-link\\\">0901 234 567 \\u2192<\\/a>\\r\\n    <\\/div>\\r\\n\\r\\n    <div class=\\\"crpc-ct-card\\\">\\r\\n      <div class=\\\"crpc-ct-icon\\\">\\ud83d\\udcac<\\/div>\\r\\n      <h3>T\\u01b0 v\\u1ea5n qua Zalo<\\/h3>\\r\\n      <p>Nh\\u1eadn h\\u00ecnh \\u1ea3nh n\\u1ed9i ngo\\u1ea1i th\\u1ea5t xe th\\u1ef1c t\\u1ebf v\\u00e0 \\u0111\\u1ecbnh v\\u1ecb b\\u00e3i giao xe.<\\/p>\\r\\n      <a href=\\\"https:\\/\\/zalo.me\\/0901234567\\\" target=\\\"_blank\\\" rel=\\\"noopener\\\" class=\\\"crpc-ct-link\\\">Chat Zalo ngay \\u2192<\\/a>\\r\\n    <\\/div>\\r\\n\\r\\n    <div class=\\\"crpc-ct-card\\\">\\r\\n      <div class=\\\"crpc-ct-icon\\\">\\u2709\\ufe0f<\\/div>\\r\\n      <h3>Email & H\\u1ee3p \\u0111\\u1ed3ng<\\/h3>\\r\\n      <p>G\\u1eedi y\\u00eau c\\u1ea7u b\\u00e1o gi\\u00e1 thu\\u00ea xe s\\u1ef1 ki\\u1ec7n, xu\\u1ea5t h\\u00f3a \\u0111\\u01a1n VAT doanh nghi\\u1ec7p.<\\/p>\\r\\n      <a href=\\\"mailto:hotro@carrental.vn\\\" class=\\\"crpc-ct-link\\\">hotro@carrental.vn \\u2192<\\/a>\\r\\n    <\\/div>\\r\\n\\r\\n    <div class=\\\"crpc-ct-card\\\">\\r\\n      <div class=\\\"crpc-ct-icon\\\">\\ud83d\\udd52<\\/div>\\r\\n      <h3>Th\\u1eddi gian ho\\u1ea1t \\u0111\\u1ed9ng<\\/h3>\\r\\n      <p>Giao nh\\u1eadn xe t\\u1eadn n\\u01a1i 24\\/7. V\\u0103n ph\\u00f2ng l\\u00e0m vi\\u1ec7c 07:30 \\u2013 21:30 h\\u1eb1ng ng\\u00e0y.<\\/p>\\r\\n      <span class=\\\"crpc-ct-link\\\" style=\\\"color:#10b981;\\\">\\u25cf \\u0110ang tr\\u1ef1c tuy\\u1ebfn<\\/span>\\r\\n    <\\/div>\\r\\n  <\\/div>\\r\\n\\r\\n  <!-- Form li\\u00ean h\\u1ec7 & B\\u1ea3n \\u0111\\u1ed3 \\u0111i\\u1ec3m giao nh\\u1eadn -->\\r\\n  <div class=\\\"crpc-ct-main\\\">\\r\\n    <div class=\\\"crpc-ct-box\\\">\\r\\n      <h2>G\\u1eedi y\\u00eau c\\u1ea7u t\\u01b0 v\\u1ea5n \\/ K\\u00fd g\\u1eedi xe<\\/h2>\\r\\n      <p class=\\\"crpc-ct-box-sub\\\">\\u0110\\u1ec3 l\\u1ea1i th\\u00f4ng tin, nh\\u00e2n vi\\u00ean \\u0111i\\u1ec1u ph\\u1ed1i s\\u1ebd g\\u1ecdi l\\u1ea1i x\\u00e1c nh\\u1eadn ngay.<\\/p>\\r\\n\\r\\n      <form id=\\\"crpcContactForm\\\">\\r\\n        <div class=\\\"crpc-ct-row\\\">\\r\\n          <div class=\\\"crpc-ct-group\\\">\\r\\n            <label for=\\\"ctName\\\">H\\u1ecd v\\u00e0 t\\u00ean *<\\/label>\\r\\n            <input type=\\\"text\\\" id=\\\"ctName\\\" class=\\\"crpc-ct-input\\\" placeholder=\\\"Nh\\u1eadp h\\u1ecd t\\u00ean c\\u1ee7a b\\u1ea1n\\\" required>\\r\\n          <\\/div>\\r\\n          <div class=\\\"crpc-ct-group\\\">\\r\\n            <label for=\\\"ctPhone\\\">S\\u1ed1 \\u0111i\\u1ec7n tho\\u1ea1i (Zalo) *<\\/label>\\r\\n            <input type=\\\"tel\\\" id=\\\"ctPhone\\\" class=\\\"crpc-ct-input\\\" placeholder=\\\"Nh\\u1eadp s\\u1ed1 \\u0111i\\u1ec7n tho\\u1ea1i\\\" required>\\r\\n          <\\/div>\\r\\n        <\\/div>\\r\\n\\r\\n        <div class=\\\"crpc-ct-group\\\">\\r\\n          <label for=\\\"ctTopic\\\">Nhu c\\u1ea7u li\\u00ean h\\u1ec7 *<\\/label>\\r\\n          <select id=\\\"ctTopic\\\" class=\\\"crpc-ct-input\\\">\\r\\n            <option value=\\\"T\\u01b0 v\\u1ea5n thu\\u00ea xe t\\u1ef1 l\\u00e1i \\/ c\\u00f3 t\\u00e0i x\\u1ebf\\\">T\\u01b0 v\\u1ea5n thu\\u00ea xe t\\u1ef1 l\\u00e1i \\/ c\\u00f3 t\\u00e0i x\\u1ebf<\\/option>\\r\\n            <option value=\\\"B\\u00e1o gi\\u00e1 thu\\u00ea xe th\\u00e1ng \\/ doanh nghi\\u1ec7p\\\">B\\u00e1o gi\\u00e1 thu\\u00ea xe d\\u00e0i h\\u1ea1n \\/ doanh nghi\\u1ec7p<\\/option>\\r\\n            <option value=\\\"\\u0110\\u0103ng k\\u00fd k\\u00fd g\\u1eedi xe nh\\u00e0n r\\u1ed7i l\\u00ean h\\u1ec7 th\\u1ed1ng\\\">\\u0110\\u0103ng k\\u00fd k\\u00fd g\\u1eedi xe nh\\u00e0n r\\u1ed7i l\\u00ean h\\u1ec7 th\\u1ed1ng<\\/option>\\r\\n            <option value=\\\"H\\u1ed7 tr\\u1ee3 \\u0111\\u01a1n \\u0111\\u1eb7t xe \\/ Khi\\u1ebfu n\\u1ea1i\\\">H\\u1ed7 tr\\u1ee3 \\u0111\\u01a1n \\u0111\\u1eb7t xe \\u0111ang thu\\u00ea<\\/option>\\r\\n          <\\/select>\\r\\n        <\\/div>\\r\\n\\r\\n        <div class=\\\"crpc-ct-group\\\">\\r\\n          <label for=\\\"ctMessage\\\">N\\u1ed9i dung chi ti\\u1ebft<\\/label>\\r\\n          <textarea id=\\\"ctMessage\\\" rows=\\\"4\\\" class=\\\"crpc-ct-textarea\\\" placeholder=\\\"VD: T\\u00f4i c\\u1ea7n thu\\u00ea VinFast VF8 t\\u1ea1i H\\u00e0 N\\u1ed9i t\\u1eeb ng\\u00e0y 20\\/11 \\u0111\\u1ebfn 23\\/11, ho\\u1eb7c th\\u00f4ng tin \\u0111\\u1eddi xe mu\\u1ed1n k\\u00fd g\\u1eedi...\\\"><\\/textarea>\\r\\n        <\\/div>\\r\\n\\r\\n        <button type=\\\"submit\\\" id=\\\"ctSubmitBtn\\\" class=\\\"crpc-ct-submit\\\">G\\u1eedi y\\u00eau c\\u1ea7u h\\u1ed7 tr\\u1ee3<\\/button>\\r\\n      <\\/form>\\r\\n    <\\/div>\\r\\n\\r\\n    <div class=\\\"crpc-ct-box\\\">\\r\\n      <h2>H\\u1ec7 th\\u1ed1ng b\\u00e3i giao nh\\u1eadn xe<\\/h2>\\r\\n      <p class=\\\"crpc-ct-box-sub\\\">Ch\\u1ecdn khu v\\u1ef1c \\u0111\\u1ec3 xem \\u0111\\u1ecba ch\\u1ec9 b\\u00e3i xe v\\u00e0 b\\u1ea3n \\u0111\\u1ed3 ch\\u1ec9 \\u0111\\u01b0\\u1eddng.<\\/p>\\r\\n\\r\\n      <div class=\\\"crpc-hub-tabs\\\">\\r\\n        <button type=\\\"button\\\" class=\\\"crpc-hub-btn active\\\" data-hub=\\\"hn\\\">H\\u00e0 N\\u1ed9i<\\/button>\\r\\n        <button type=\\\"button\\\" class=\\\"crpc-hub-btn\\\" data-hub=\\\"dn\\\">\\u0110\\u00e0 N\\u1eb5ng<\\/button>\\r\\n        <button type=\\\"button\\\" class=\\\"crpc-hub-btn\\\" data-hub=\\\"hcm\\\">TP. H\\u1ed3 Ch\\u00ed Minh<\\/button>\\r\\n      <\\/div>\\r\\n\\r\\n      <div class=\\\"crpc-hub-info\\\" id=\\\"crpcHubInfo\\\">\\r\\n        <strong>B\\u00e3i xe ch\\u00ednh H\\u00e0 N\\u1ed9i:<\\/strong> S\\u1ed1 16 Ph\\u1ea1m H\\u00f9ng, Nam T\\u1eeb Li\\u00eam, H\\u00e0 N\\u1ed9i (H\\u1ed7 tr\\u1ee3 giao xe t\\u1eadn n\\u01a1i & S\\u00e2n bay N\\u1ed9i B\\u00e0i).\\r\\n      <\\/div>\\r\\n\\r\\n      <iframe id=\\\"crpcHubMap\\\" class=\\\"crpc-map-frame\\\" loading=\\\"lazy\\\" referrerpolicy=\\\"no-referrer-when-downgrade\\\"\\r\\n        src=\\\"https:\\/\\/maps.google.com\\/maps?q=16%20Ph%E1%BA%A1m%20H%C3%B9ng,%20Nam%20T%E1%BB%AB%20Li%C3%AAm,%20H%C3%A0%20N%E1%BB%99i&t=&z=15&ie=UTF8&iwloc=&output=embed\\\">\\r\\n      <\\/iframe>\\r\\n    <\\/div>\\r\\n  <\\/div>\\r\\n\\r\\n  <!-- C\\u00e2u h\\u1ecfi th\\u01b0\\u1eddng g\\u1eb7p (FAQ) -->\\r\\n  <div class=\\\"crpc-faq-wrap\\\">\\r\\n    <h2>C\\u00e2u h\\u1ecfi th\\u01b0\\u1eddng g\\u1eb7p khi thu\\u00ea xe<\\/h2>\\r\\n\\r\\n    <div class=\\\"crpc-faq-item open\\\">\\r\\n      <div class=\\\"crpc-faq-q\\\">1. Th\\u1ee7 t\\u1ee5c thu\\u00ea xe t\\u1ef1 l\\u00e1i c\\u1ea7n chu\\u1ea9n b\\u1ecb gi\\u1ea5y t\\u1edd g\\u00ec? <span>\\u25be<\\/span><\\/div>\\r\\n      <div class=\\\"crpc-faq-a\\\">Kh\\u00e1ch h\\u00e0ng ch\\u1ec9 c\\u1ea7n c\\u00f3 C\\u0103n c\\u01b0\\u1edbc c\\u00f4ng d\\u00e2n (CCCD) g\\u1eafn chip v\\u00e0 Gi\\u1ea5y ph\\u00e9p l\\u00e1i xe (GPLX) h\\u1ea1ng B1 tr\\u1edf l\\u00ean c\\u00f2n hi\\u1ec7u l\\u1ef1c. Th\\u1ee7 t\\u1ee5c \\u0111\\u1ed1i chi\\u1ebfu ch\\u1ec9 m\\u1ea5t 5 ph\\u00fat khi nh\\u1eadn xe.<\\/div>\\r\\n    <\\/div>\\r\\n\\r\\n    <div class=\\\"crpc-faq-item\\\">\\r\\n      <div class=\\\"crpc-faq-q\\\">2. Quy \\u0111\\u1ecbnh \\u0111\\u1eb7t c\\u1ecdc th\\u1ebf ch\\u1ea5p khi nh\\u1eadn xe nh\\u01b0 th\\u1ebf n\\u00e0o? <span>\\u25be<\\/span><\\/div>\\r\\n      <div class=\\\"crpc-faq-a\\\">T\\u00f9y theo d\\u00f2ng xe (VinFast VF3, VF5, VF8 ho\\u1eb7c xe sang), m\\u1ee9c th\\u1ebf ch\\u1ea5p dao \\u0111\\u1ed9ng t\\u1eeb 5 \\u2013 15 tri\\u1ec7u \\u0111\\u1ed3ng (ho\\u1eb7c xe m\\u00e1y k\\u00e8m gi\\u1ea5y \\u0111\\u0103ng k\\u00fd xe ch\\u00ednh ch\\u1ee7) v\\u00e0 \\u0111\\u01b0\\u1ee3c ho\\u00e0n tr\\u1ea3 100% ngay khi b\\u00e0n giao l\\u1ea1i xe.<\\/div>\\r\\n    <\\/div>\\r\\n\\r\\n    <div class=\\\"crpc-faq-item\\\">\\r\\n      <div class=\\\"crpc-faq-q\\\">3. H\\u1ec7 th\\u1ed1ng c\\u00f3 h\\u1ed7 tr\\u1ee3 giao xe t\\u1eadn nh\\u00e0 ho\\u1eb7c s\\u00e2n bay kh\\u00f4ng? <span>\\u25be<\\/span><\\/div>\\r\\n      <div class=\\\"crpc-faq-a\\\">C\\u00f3. Ch\\u00fang t\\u00f4i h\\u1ed7 tr\\u1ee3 giao nh\\u1eadn xe t\\u1eadn n\\u01a1i t\\u1ea1i n\\u1ed9i th\\u00e0nh H\\u00e0 N\\u1ed9i, \\u0110\\u00e0 N\\u1eb5ng, TP.HCM v\\u00e0 c\\u00e1c s\\u1ea3nh s\\u00e2n bay 24\\/7. Mi\\u1ec5n ph\\u00ed giao xe trong b\\u00e1n k\\u00ednh 5 km t\\u1eeb b\\u00e3i xe g\\u1ea7n nh\\u1ea5t.<\\/div>\\r\\n    <\\/div>\\r\\n\\r\\n    <div class=\\\"crpc-faq-item\\\">\\r\\n      <div class=\\\"crpc-faq-q\\\">4. Ch\\u1ee7 xe mu\\u1ed1n k\\u00fd g\\u1eedi \\u00f4 t\\u00f4 nh\\u00e0n r\\u1ed7i l\\u00ean n\\u1ec1n t\\u1ea3ng c\\u1ea7n \\u0111i\\u1ec1u ki\\u1ec7n g\\u00ec? <span>\\u25be<\\/span><\\/div>\\r\\n      <div class=\\\"crpc-faq-a\\\">Xe s\\u1ea3n xu\\u1ea5t t\\u1eeb n\\u0103m 2020 tr\\u1edf l\\u00ean, c\\u00f3 b\\u1ea3o hi\\u1ec3m th\\u00e2n v\\u1ecf v\\u00e0 \\u0111\\u0103ng ki\\u1ec3m c\\u00f2n h\\u1ea1n. B\\u1ea1n ch\\u1ec9 c\\u1ea7n \\u0111\\u1ec3 l\\u1ea1i th\\u00f4ng tin \\u1edf form ph\\u00eda tr\\u00ean, b\\u1ed9 ph\\u1eadn th\\u1ea9m \\u0111\\u1ecbnh s\\u1ebd li\\u00ean h\\u1ec7 ki\\u1ec3m tra xe v\\u00e0 k\\u00fd h\\u1ee3p \\u0111\\u1ed3ng h\\u1ee3p t\\u00e1c.<\\/div>\\r\\n    <\\/div>\\r\\n  <\\/div>\\r\\n<\\/div>\\r\\n\\r\\n<script>\\r\\n(function() {\\r\\n  const hubs = {\\r\\n    hn: {\\r\\n      text: \'<strong>B\\u00e3i xe ch\\u00ednh H\\u00e0 N\\u1ed9i:<\\/strong> S\\u1ed1 16 Ph\\u1ea1m H\\u00f9ng, Nam T\\u1eeb Li\\u00eam, H\\u00e0 N\\u1ed9i (H\\u1ed7 tr\\u1ee3 giao xe t\\u1eadn n\\u01a1i & S\\u00e2n bay N\\u1ed9i B\\u00e0i).\',\\r\\n      map: \'https:\\/\\/maps.google.com\\/maps?q=16%20Ph%E1%BA%A1m%20H%C3%B9ng,%20Nam%20T%E1%BB%AB%20Li%C3%AAm,%20H%C3%A0%20N%E1%BB%99i&t=&z=15&ie=UTF8&iwloc=&output=embed\'\\r\\n    },\\r\\n    dn: {\\r\\n      text: \'<strong>B\\u00e3i xe \\u0110\\u00e0 N\\u1eb5ng:<\\/strong> Qu\\u1eadn H\\u1ea3i Ch\\u00e2u, TP. \\u0110\\u00e0 N\\u1eb5ng (Giao xe mi\\u1ec5n ph\\u00ed t\\u1ea1i S\\u00e2n bay Qu\\u1ed1c t\\u1ebf \\u0110\\u00e0 N\\u1eb5ng & kh\\u00e1ch s\\u1ea1n ven bi\\u1ec3n).\',\\r\\n      map: \'https:\\/\\/maps.google.com\\/maps?q=H%E1%BA%A3i%20Ch%C3%A2u,%20%C4%90%C3%A0%20N%E1%BA%B5ng&t=&z=14&ie=UTF8&iwloc=&output=embed\'\\r\\n    },\\r\\n    hcm: {\\r\\n      text: \'<strong>B\\u00e3i xe TP. H\\u1ed3 Ch\\u00ed Minh:<\\/strong> Khu v\\u1ef1c trung t\\u00e2m Qu\\u1eadn 1, TP. H\\u1ed3 Ch\\u00ed Minh (S\\u1eb5n s\\u00e0ng giao xe nhanh 24\\/7).\',\\r\\n      map: \'https:\\/\\/maps.google.com\\/maps?q=Qu%E1%BA%ADn%201,%20Th%C3%A0nh%20ph%E1%BB%91%20H%E1%BB%93%20Ch%C3%AD%20Minh&t=&z=14&ie=UTF8&iwloc=&output=embed\'\\r\\n    }\\r\\n  };\\r\\n\\r\\n  document.querySelectorAll(\'#crpcContactPage .crpc-hub-btn\').forEach(btn => {\\r\\n    btn.addEventListener(\'click\', function() {\\r\\n      document.querySelectorAll(\'#crpcContactPage .crpc-hub-btn\').forEach(b => b.classList.remove(\'active\'));\\r\\n      this.classList.add(\'active\');\\r\\n      const hub = hubs[this.dataset.hub];\\r\\n      if (hub) {\\r\\n        document.getElementById(\'crpcHubInfo\').innerHTML = hub.text;\\r\\n        document.getElementById(\'crpcHubMap\').src = hub.map;\\r\\n      }\\r\\n    });\\r\\n  });\\r\\n\\r\\n  document.querySelectorAll(\'#crpcContactPage .crpc-faq-q\').forEach(q => {\\r\\n    q.addEventListener(\'click\', function() {\\r\\n      this.parentElement.classList.toggle(\'open\');\\r\\n    });\\r\\n  });\\r\\n\\r\\n  const ctForm = document.getElementById(\'crpcContactForm\');\\r\\n  if (ctForm) {\\r\\n    ctForm.addEventListener(\'submit\', async function(e) {\\r\\n      e.preventDefault();\\r\\n      const btn = document.getElementById(\'ctSubmitBtn\');\\r\\n      const oldText = btn.textContent;\\r\\n      btn.disabled = true;\\r\\n      btn.textContent = \'\\u0110ang g\\u1eedi y\\u00eau c\\u1ea7u...\';\\r\\n\\r\\n      const formData = new FormData();\\r\\n      formData.append(\'action\', \'crpc_save_contact_inquiry\');\\r\\n      formData.append(\'name\', document.getElementById(\'ctName\').value.trim());\\r\\n      formData.append(\'phone\', document.getElementById(\'ctPhone\').value.trim());\\r\\n      formData.append(\'topic\', document.getElementById(\'ctTopic\').value);\\r\\n      formData.append(\'message\', document.getElementById(\'ctMessage\').value.trim());\\r\\n\\r\\n      try {\\r\\n        const ajaxUrl = window.crpcAjaxUrl || \'\\/wp-admin\\/admin-ajax.php\';\\r\\n        await fetch(ajaxUrl, { method: \'POST\', body: formData });\\r\\n      } catch (err) {}\\r\\n\\r\\n      alert(\'\\u0110\\u00e3 g\\u1eedi th\\u00f4ng tin li\\u00ean h\\u1ec7 th\\u00e0nh c\\u00f4ng! \\u0110\\u1ed9i ng\\u0169 \\u0111i\\u1ec1u ph\\u1ed1i s\\u1ebd g\\u1ecdi l\\u1ea1i cho b\\u1ea1n trong \\u00edt ph\\u00fat.\');\\r\\n      ctForm.reset();\\r\\n      btn.disabled = false;\\r\\n      btn.textContent = oldText;\\r\\n    });\\r\\n  }\\r\\n})();\\r\\n<\\/script>\"},\"elements\":[],\"widgetType\":\"html\"}],\"isInner\":false},{\"id\":\"d6bf36a\",\"elType\":\"container\",\"settings\":{\"structure\":\"20\",\"margin\":{\"unit\":\"px\",\"top\":\"0\",\"right\":\"0\",\"bottom\":\"50\",\"left\":\"0\",\"isLinked\":false},\"flex_direction\":\"row\",\"flex_gap\":{\"size\":30,\"column\":\"30\",\"row\":\"30\",\"unit\":\"px\",\"isLinked\":true},\"flex_gap_mobile\":{\"column\":\"\",\"row\":\"\",\"isLinked\":true,\"unit\":\"px\",\"size\":null},\"padding\":{\"unit\":\"px\",\"top\":\"0\",\"right\":\"0\",\"bottom\":\"0\",\"left\":\"0\",\"isLinked\":true}},\"elements\":[{\"id\":\"845e1d3\",\"elType\":\"container\",\"settings\":{\"_column_size\":50,\"width\":{\"size\":67,\"unit\":\"%\"},\"padding_tablet\":{\"unit\":\"px\",\"top\":\"0\",\"right\":\"0\",\"bottom\":\"0\",\"left\":\"0\",\"isLinked\":true},\"padding\":{\"unit\":\"px\",\"top\":\"0\",\"right\":\"0\",\"bottom\":\"0\",\"left\":\"0\",\"isLinked\":true},\"content_width\":\"full\"},\"elements\":[],\"isInner\":true},{\"id\":\"d372007\",\"elType\":\"container\",\"settings\":{\"_column_size\":50,\"width\":{\"size\":33,\"unit\":\"%\"},\"flex_justify_content\":\"center\",\"align\":\"flex-end\",\"flex_justify_content_tablet\":\"center\",\"align_tablet\":\"center\",\"padding_tablet\":{\"unit\":\"px\",\"top\":\"0\",\"right\":\"0\",\"bottom\":\"0\",\"left\":\"0\",\"isLinked\":true},\"padding\":{\"unit\":\"px\",\"top\":\"0\",\"right\":\"0\",\"bottom\":\"0\",\"left\":\"0\",\"isLinked\":true},\"content_width\":\"full\"},\"elements\":[{\"id\":\"249917e\",\"elType\":\"widget\",\"settings\":{\"text\":\"View All\",\"align\":\"right\",\"typography_typography\":\"custom\",\"typography_font_size\":{\"unit\":\"px\",\"size\":15,\"sizes\":[]},\"typography_font_weight\":\"600\",\"typography_text_transform\":\"uppercase\",\"background_color\":\"#02010100\",\"border_border\":\"solid\",\"border_width\":{\"unit\":\"px\",\"top\":\"2\",\"right\":\"2\",\"bottom\":\"2\",\"left\":\"2\",\"isLinked\":true},\"border_color\":\"#687279\",\"border_radius\":{\"unit\":\"px\",\"top\":\"0\",\"right\":\"0\",\"bottom\":\"0\",\"left\":\"0\",\"isLinked\":true},\"__globals__\":{\"button_text_color\":\"globals\\/colors?id=blocksy_palette_4\",\"button_background_hover_color\":\"globals\\/colors?id=blocksy_palette_2\",\"button_hover_border_color\":\"globals\\/colors?id=blocksy_palette_2\"},\"hover_color\":\"#FFFFFF\",\"align_mobile\":\"center\"},\"elements\":[],\"widgetType\":\"button\"}],\"isInner\":true}],\"isInner\":false},{\"id\":\"52f0a3e\",\"elType\":\"container\",\"settings\":{\"flex_direction\":\"row\",\"flex_align_items\":\"stretch\",\"flex_gap\":{\"size\":10,\"column\":\"10\",\"row\":\"10\",\"unit\":\"px\"},\"flex_justify_content\":\"center\",\"margin\":{\"unit\":\"px\",\"top\":\"0\",\"right\":\"0\",\"bottom\":\"130\",\"left\":\"0\",\"isLinked\":false},\"margin_tablet\":{\"unit\":\"px\",\"top\":\"0\",\"right\":\"0\",\"bottom\":\"80\",\"left\":\"0\",\"isLinked\":false},\"padding\":{\"unit\":\"px\",\"top\":\"0\",\"right\":\"0\",\"bottom\":\"0\",\"left\":\"0\",\"isLinked\":true}},\"elements\":[{\"id\":\"f2f036b\",\"elType\":\"widget\",\"settings\":{\"shortcode\":\"[products limit=\\\"4\\\" columns=\\\"4\\\"]\",\"_element_width_tablet\":\"inherit\"},\"elements\":[],\"widgetType\":\"shortcode\"}],\"isInner\":false}]'),
