(3550, 1, '2026-11-16 08:40:24', '2026-11-16 08:40:24', '{\n    \"custom_css[blocksy]\": {\n        \"value\": \"@media (min-width: 691px) and (max-width: 1000px) {\\n\\t.final-sale-home-cta [data-products] {\\n\\t\\t--shop-columns: repeat(3, minmax(0, 1fr))\\n\\t}\\n}\\n\\n.final-sale-home-cta .product {\\n\\t--theme-text-color: rgba(255, 255, 255, 0.5);\\n\\t--theme-heading-color: #fff;\\n}\\n\\n.elementor-icon-box-content {\\n\\tmargin-top: -4px;\\n}\\n\\n.wpforms-container {\\n\\tmargin-bottom: 0px;\\n}\\n\\n.ct-widget-cover-block {\\n\\tpadding: 40px;\\n}/* Bo g\\u00f3c \\u1ea3nh xe trong danh s\\u00e1ch thu\\u00ea */\\n.woocommerce-cart-form .product-thumbnail img {\\n    border-radius: 8px;\\n    width: 90px !important;\\n    object-fit: cover;\\n}\\n\\n/* L\\u00e0m n\\u1ed5i b\\u1eadt t\\u00ean xe v\\u00e0 \\u0111\\u01a1n gi\\u00e1/ng\\u00e0y */\\n.woocommerce-cart-form .product-name a {\\n    font-weight: 700;\\n    color: #111827;\\n    font-size: 15px;\\n    text-decoration: none;\\n}\\n\\n/* Bo g\\u00f3c \\u00f4 nh\\u1eadp ng\\u00e0y thu\\u00ea (- 1 +) */\\n.woocommerce-cart-form .quantity {\\n    border-radius: 6px;\\n    overflow: hidden;\\n}\\n\\n/* Bo g\\u00f3c v\\u00e0 \\u0111\\u1ed5 b\\u00f3ng nh\\u1eb9 cho khung T\\u1ed5ng ti\\u1ec1n thu\\u00ea b\\u00ean ph\\u1ea3i */\\n.cart-collaterals .cart_totals {\\n    border-radius: 12px;\\n    border: 1px solid #e5e7eb;\\n    box-shadow: 0 8px 24px rgba(0, 0, 0, 0.04);\\n    background: #ffffff;\\n}\\n\\n/* N\\u00fat Ti\\u1ebfn h\\u00e0nh \\u0111\\u1eb7t xe bo g\\u00f3c hi\\u1ec7n \\u0111\\u1ea1i */\\n.cart-collaterals .checkout-button {\\n    border-radius: 8px !important;\\n    font-weight: 700 !important;\\n    padding: 14px 20px !important;\\n    transition: background-color 0.2s ease;\\n}\\n\\n/* \\u00d4 nh\\u1eadp m\\u00e3 gi\\u1ea3m gi\\u00e1 v\\u00e0 n\\u00fat \\u00c1p d\\u1ee5ng */\\n.woocommerce-cart-form #coupon_code {\\n    border-radius: 6px;\\n    height: 44px;\\n}\\n.woocommerce-cart-form button[name=\\\"apply_coupon\\\"],\\n.woocommerce-cart-form button[name=\\\"update_cart\\\"] {\\n    border-radius: 6px !important;\\n    height: 44px;\\n}\",\n        \"type\": \"custom_css\",\n        \"user_id\": 1,\n        \"date_modified_gmt\": \"2026-11-16 08:40:15\"\n    }\n}', '', '', 'trash', 'closed', 'closed', '', '529a425e-5ae0-473d-86d1-a943f790b38a', '', '', '2026-11-16 08:40:24', '2026-11-16 08:40:24', '', 0, 'https://localhost/carrental/?p=3550', 0, 'customize_changeset', '', 0),
(3551, 1, '2026-11-16 08:40:24', '2026-11-16 08:40:24', '@media (min-width: 691px) and (max-width: 1000px) {\n	.final-sale-home-cta [data-products] {\n		--shop-columns: repeat(3, minmax(0, 1fr))\n	}\n}\n\n.final-sale-home-cta .product {\n	--theme-text-color: rgba(255, 255, 255, 0.5);\n	--theme-heading-color: #fff;\n}\n\n.elementor-icon-box-content {\n	margin-top: -4px;\n}\n\n.wpforms-container {\n	margin-bottom: 0px;\n}\n\n.ct-widget-cover-block {\n	padding: 40px;\n}/* Bo góc ảnh xe trong danh sách thuê */\n.woocommerce-cart-form .product-thumbnail img {\n    border-radius: 8px;\n    width: 90px !important;\n    object-fit: cover;\n}\n\n/* Làm nổi bật tên xe và đơn giá/ngày */\n.woocommerce-cart-form .product-name a {\n    font-weight: 700;\n    color: #111827;\n    font-size: 15px;\n    text-decoration: none;\n}\n\n/* Bo góc ô nhập ngày thuê (- 1 +) */\n.woocommerce-cart-form .quantity {\n    border-radius: 6px;\n    overflow: hidden;\n}\n\n/* Bo góc và đổ bóng nhẹ cho khung Tổng tiền thuê bên phải */\n.cart-collaterals .cart_totals {\n    border-radius: 12px;\n    border: 1px solid #e5e7eb;\n    box-shadow: 0 8px 24px rgba(0, 0, 0, 0.04);\n    background: #ffffff;\n}\n\n/* Nút Tiến hành đặt xe bo góc hiện đại */\n.cart-collaterals .checkout-button {\n    border-radius: 8px !important;\n    font-weight: 700 !important;\n    padding: 14px 20px !important;\n    transition: background-color 0.2s ease;\n}\n\n/* Ô nhập mã giảm giá và nút Áp dụng */\n.woocommerce-cart-form #coupon_code {\n    border-radius: 6px;\n    height: 44px;\n}\n.woocommerce-cart-form button[name=\"apply_coupon\"],\n.woocommerce-cart-form button[name=\"update_cart\"] {\n    border-radius: 6px !important;\n    height: 44px;\n}', 'blocksy', '', 'inherit', 'closed', 'closed', '', '115-revision-v1', '', '', '2026-11-16 08:40:24', '2026-11-16 08:40:24', '', 115, 'https://localhost/carrental/?p=3551', 0, 'revision', '', 0);
