(3568, 1, '2026-11-16 13:15:54', '2026-11-16 13:15:54', '{\n    \"custom_css[blocksy]\": {\n        \"value\": \"@media (min-width: 691px) and (max-width: 1000px) {\\n\\t.final-sale-home-cta [data-products] {\\n\\t\\t--shop-columns: repeat(3, minmax(0, 1fr))\\n\\t}\\n}\\n\\n.final-sale-home-cta .product {\\n\\t--theme-text-color: rgba(255, 255, 255, 0.5);\\n\\t--theme-heading-color: #fff;\\n}\\n\\n.elementor-icon-box-content {\\n\\tmargin-top: -4px;\\n}\\n\\n.wpforms-container {\\n\\tmargin-bottom: 0px;\\n}\\n\\n.ct-widget-cover-block {\\n\\tpadding: 40px;\\n}/* Bo g\\u00f3c \\u1ea3nh xe trong danh s\\u00e1ch thu\\u00ea */\\n.woocommerce-cart-form .product-thumbnail img {\\n    border-radius: 8px;\\n    width: 90px !important;\\n    object-fit: cover;\\n}\\n\\n/* L\\u00e0m n\\u1ed5i b\\u1eadt t\\u00ean xe v\\u00e0 \\u0111\\u01a1n gi\\u00e1/ng\\u00e0y */\\n.woocommerce-cart-form .product-name a {\\n    font-weight: 700;\\n    color: #111827;\\n    font-size: 15px;\\n    text-decoration: none;\\n}\\n\\n/* Bo g\\u00f3c \\u00f4 nh\\u1eadp ng\\u00e0y thu\\u00ea (- 1 +) */\\n.woocommerce-cart-form .quantity {\\n    border-radius: 6px;\\n    overflow: hidden;\\n}\\n\\n/* Bo g\\u00f3c v\\u00e0 \\u0111\\u1ed5 b\\u00f3ng nh\\u1eb9 cho khung T\\u1ed5ng ti\\u1ec1n thu\\u00ea b\\u00ean ph\\u1ea3i */\\n.cart-collaterals .cart_totals {\\n    border-radius: 12px;\\n    border: 1px solid #e5e7eb;\\n    box-shadow: 0 8px 24px rgba(0, 0, 0, 0.04);\\n    background: #ffffff;\\n}\\n\\n/* N\\u00fat Ti\\u1ebfn h\\u00e0nh \\u0111\\u1eb7t xe bo g\\u00f3c hi\\u1ec7n \\u0111\\u1ea1i */\\n.cart-collaterals .checkout-button {\\n    border-radius: 8px !important;\\n    font-weight: 700 !important;\\n    padding: 14px 20px !important;\\n    transition: background-color 0.2s ease;\\n}\\n\\n/* \\u00d4 nh\\u1eadp m\\u00e3 gi\\u1ea3m gi\\u00e1 v\\u00e0 n\\u00fat \\u00c1p d\\u1ee5ng */\\n.woocommerce-cart-form #coupon_code {\\n    border-radius: 6px;\\n    height: 44px;\\n}\\n.woocommerce-cart-form button[name=\\\"apply_coupon\\\"],\\n.woocommerce-cart-form button[name=\\\"update_cart\\\"] {\\n    border-radius: 6px !important;\\n    height: 44px;\\n}/* 1. \\u1ea8n ho\\u00e0n to\\u00e0n d\\u00f2ng Shipment / Calculate shipping th\\u1eeba trong khung T\\u1ed5ng ti\\u1ec1n thu\\u00ea */\\n.cart_totals tr.woocommerce-shipping-totals,\\n.cart_totals tr.shipping {\\n    display: none !important;\\n}\\n\\n/* 2. Giao di\\u1ec7n khung Th\\u00f4ng tin l\\u1ecbch tr\\u00ecnh & Ch\\u1ed1t thu\\u00ea xe \\u0111\\u1ed3ng b\\u1ed9 n\\u1ec1n tr\\u1eafng - n\\u00fat \\u0111\\u1ecf */\\n.crpc-cart-booking-box {\\n    margin-top: 28px;\\n    padding: 24px;\\n    background: #ffffff;\\n    border: 1px solid #e5e7eb;\\n    border-radius: 12px;\\n    box-shadow: 0 4px 16px rgba(0, 0, 0, 0.04);\\n}\\n\\n.crpc-cb-header {\\n    margin-bottom: 18px;\\n    padding-bottom: 14px;\\n    border-bottom: 1px solid #f3f4f6;\\n}\\n\\n.crpc-cb-header h3 {\\n    margin: 0 0 4px 0;\\n    font-size: 18px;\\n    font-weight: 700;\\n    color: #111827;\\n}\\n\\n.crpc-cb-header p {\\n    margin: 0;\\n    font-size: 13px;\\n    color: #6b7280;\\n}\\n\\n.crpc-cb-grid {\\n    display: grid;\\n    grid-template-columns: repeat(2, 1fr);\\n    gap: 16px;\\n}\\n\\n.crpc-cb-field {\\n    display: flex;\\n    flex-direction: column;\\n    gap: 6px;\\n}\\n\\n.crpc-cb-field.crpc-cb-full {\\n    grid-column: span 2;\\n}\\n\\n.crpc-cb-field label {\\n    font-size: 13px;\\n    font-weight: 600;\\n    color: #374151;\\n}\\n\\n.crpc-cb-input {\\n    width: 100%;\\n    height: 44px;\\n    padding: 0 12px;\\n    border: 1px solid #d1d5db;\\n    border-radius: 8px;\\n    background: #ffffff;\\n    color: #111827;\\n    font-size: 14px;\\n    outline: none;\\n    transition: border-color 0.2s, box-shadow 0.2s;\\n}\\n\\n.crpc-cb-input:focus {\\n    border-color: #d9383a;\\n    box-shadow: 0 0 0 3px rgba(217, 56, 58, 0.12);\\n}\\n\\n.crpc-cb-footer-bar {\\n    margin-top: 16px;\\n    padding-top: 14px;\\n    border-top: 1px solid #f3f4f6;\\n    display: flex;\\n    justify-content: space-between;\\n    align-items: center;\\n    flex-wrap: wrap;\\n    gap: 12px;\\n}\\n\\n.crpc-cb-duration {\\n    font-size: 13px;\\n    color: #4b5563;\\n}\\n\\n.crpc-cb-sync-btn {\\n    background-color: #fef2f2;\\n    color: #d9383a;\\n    border: 1px solid #fecaca;\\n    padding: 8px 14px;\\n    border-radius: 8px;\\n    font-size: 13px;\\n    font-weight: 700;\\n    cursor: pointer;\\n    transition: all 0.2s;\\n}\\n\\n.crpc-cb-sync-btn:hover {\\n    background-color: #d9383a;\\n    color: #ffffff;\\n    border-color: #d9383a;\\n}\\n\\n@media (max-width: 640px) {\\n    .crpc-cb-grid {\\n        grid-template-columns: 1fr;\\n    }\\n    .crpc-cb-field.crpc-cb-full {\\n        grid-column: span 1;\\n    }\\n}\",\n        \"type\": \"custom_css\",\n        \"user_id\": 1,\n        \"date_modified_gmt\": \"2026-11-16 13:15:54\"\n    }\n}', '', '', 'trash', 'closed', 'closed', '', 'bf055a71-8533-4565-8be3-2f860f4b945d', '', '', '2026-11-16 13:15:54', '2026-11-16 13:15:54', '', 0, 'https://localhost/carrental/?p=3568', 0, 'customize_changeset', '', 0),
(3569, 1, '2026-11-16 13:15:54', '2026-11-16 13:15:54', '@media (min-width: 691px) and (max-width: 1000px) {\n	.final-sale-home-cta [data-products] {\n		--shop-columns: repeat(3, minmax(0, 1fr))\n	}\n}\n\n.final-sale-home-cta .product {\n	--theme-text-color: rgba(255, 255, 255, 0.5);\n	--theme-heading-color: #fff;\n}\n\n.elementor-icon-box-content {\n	margin-top: -4px;\n}\n\n.wpforms-container {\n	margin-bottom: 0px;\n}\n\n.ct-widget-cover-block {\n	padding: 40px;\n}/* Bo góc ảnh xe trong danh sách thuê */\n.woocommerce-cart-form .product-thumbnail img {\n    border-radius: 8px;\n    width: 90px !important;\n    object-fit: cover;\n}\n\n/* Làm nổi bật tên xe và đơn giá/ngày */\n.woocommerce-cart-form .product-name a {\n    font-weight: 700;\n    color: #111827;\n    font-size: 15px;\n    text-decoration: none;\n}\n\n/* Bo góc ô nhập ngày thuê (- 1 +) */\n.woocommerce-cart-form .quantity {\n    border-radius: 6px;\n    overflow: hidden;\n}\n\n/* Bo góc và đổ bóng nhẹ cho khung Tổng tiền thuê bên phải */\n.cart-collaterals .cart_totals {\n    border-radius: 12px;\n    border: 1px solid #e5e7eb;\n    box-shadow: 0 8px 24px rgba(0, 0, 0, 0.04);\n    background: #ffffff;\n}\n\n/* Nút Tiến hành đặt xe bo góc hiện đại */\n.cart-collaterals .checkout-button {\n    border-radius: 8px !important;\n    font-weight: 700 !important;\n    padding: 14px 20px !important;\n    transition: background-color 0.2s ease;\n}\n\n/* Ô nhập mã giảm giá và nút Áp dụng */\n.woocommerce-cart-form #coupon_code {\n    border-radius: 6px;\n    height: 44px;\n}\n.woocommerce-cart-form button[name=\"apply_coupon\"],\n.woocommerce-cart-form button[name=\"update_cart\"] {\n    border-radius: 6px !important;\n    height: 44px;\n}/* 1. Ẩn hoàn toàn dòng Shipment / Calculate shipping thừa trong khung Tổng tiền thuê */\n.cart_totals tr.woocommerce-shipping-totals,\n.cart_totals tr.shipping {\n    display: none !important;\n}\n\n/* 2. Giao diện khung Thông tin lịch trình & Chốt thuê xe đồng bộ nền trắng - nút đỏ */\n.crpc-cart-booking-box {\n    margin-top: 28px;\n    padding: 24px;\n    background: #ffffff;\n    border: 1px solid #e5e7eb;\n    border-radius: 12px;\n    box-shadow: 0 4px 16px rgba(0, 0, 0, 0.04);\n}\n\n.crpc-cb-header {\n    margin-bottom: 18px;\n    padding-bottom: 14px;\n    border-bottom: 1px solid #f3f4f6;\n}\n\n.crpc-cb-header h3 {\n    margin: 0 0 4px 0;\n    font-size: 18px;\n    font-weight: 700;\n    color: #111827;\n}\n\n.crpc-cb-header p {\n    margin: 0;\n    font-size: 13px;\n    color: #6b7280;\n}\n\n.crpc-cb-grid {\n    display: grid;\n    grid-template-columns: repeat(2, 1fr);\n    gap: 16px;\n}\n\n.crpc-cb-field {\n    display: flex;\n    flex-direction: column;\n    gap: 6px;\n}\n\n.crpc-cb-field.crpc-cb-full {\n    grid-column: span 2;\n}\n\n.crpc-cb-field label {\n    font-size: 13px;\n    font-weight: 600;\n    color: #374151;\n}\n\n.crpc-cb-input {\n    width: 100%;\n    height: 44px;\n    padding: 0 12px;\n    border: 1px solid #d1d5db;\n    border-radius: 8px;\n    background: #ffffff;\n    color: #111827;\n    font-size: 14px;\n    outline: none;\n    transition: border-color 0.2s, box-shadow 0.2s;\n}\n\n.crpc-cb-input:focus {\n    border-color: #d9383a;\n    box-shadow: 0 0 0 3px rgba(217, 56, 58, 0.12);\n}\n\n.crpc-cb-footer-bar {\n    margin-top: 16px;\n    padding-top: 14px;\n    border-top: 1px solid #f3f4f6;\n    display: flex;\n    justify-content: space-between;\n    align-items: center;\n    flex-wrap: wrap;\n    gap: 12px;\n}\n\n.crpc-cb-duration {\n    font-size: 13px;\n    color: #4b5563;\n}\n\n.crpc-cb-sync-btn {\n    background-color: #fef2f2;\n    color: #d9383a;\n    border: 1px solid #fecaca;\n    padding: 8px 14px;\n    border-radius: 8px;\n    font-size: 13px;\n    font-weight: 700;\n    cursor: pointer;\n    transition: all 0.2s;\n}\n\n.crpc-cb-sync-btn:hover {\n    background-color: #d9383a;\n    color: #ffffff;\n    border-color: #d9383a;\n}\n\n@media (max-width: 640px) {\n    .crpc-cb-grid {\n        grid-template-columns: 1fr;\n    }\n    .crpc-cb-field.crpc-cb-full {\n        grid-column: span 1;\n    }\n}', 'blocksy', '', 'inherit', 'closed', 'closed', '', '115-revision-v1', '', '', '2026-11-16 13:15:54', '2026-11-16 13:15:54', '', 115, 'https://localhost/carrental/?p=3569', 0, 'revision', '', 0),
